  "2분기 매출 7,308억원(+11%), 영업이익 735억원(+2%)으로 영업이익이 기대치를 10.9% 밑돌았어요. 회사가 미국 연간 매출 가이던스를 900억원에서 800억원으로 낮추자 JP모건은 목표가를 14만원에서 9만원으로 내렸어요. "
  "주가는 8월 7일 102,100원에서 13일 78,700원으로 4거래일 만에 23% 하락했고 공매도 과열종목으로 지정됐어요.",
