# ---- 케어젠(214370)
N("214370", "2026-09-07", "-", "cat", "주가 70% 급락에 자사주 매각 자금계획 차질(15만원대→4만3,750원)",
  "케어젠 주가가 2월 15만원대에서 9월 3일 4만3,750원으로 반년 만에 70% 넘게 떨어졌어요. 개정 상법에 따라 자사주 38만3,577주를 팔아 약 500억원의 R&D 자금(CG-P5·CG-T1 임상)을 마련하려 했지만 현재가로는 약 168억원에 그쳐 330억원 넘게 모자라게 됐어요. 회사는 부족분을 채우려 추가 매각할 계획은 없다고 밝혔고, 하락 국면에서 자사주 오버행 부담이 겹친 상황이었어요.",
  "https://dealsite.co.kr/articles/168414", "딜사이트")
# ---- 아모레퍼시픽(090430)
N("090430", "2024-04-30", "+", "earn", "1Q24 영업이익 727억원, 기대치 42.8% 상회에 +8.7% 52주 신고가",
  "아모레퍼시픽의 1분기 영업이익이 727억원으로 전년 대비 12.9% 늘며 시장 기대를 42.8% 웃돌았어요(매출 9,115억원, -0.2%). 해외법인 영업이익이 316억원으로 중국 법인의 예상 밖 회복, 미국 판매 호조, 코스알엑스 실적이 돋보였고, 4월 30일 주가는 8.66% 오른 16만9,400원으로 장중 52주 신고가 17만원을 찍었어요. 한국투자·신한투자증권이 목표가를 22만원으로 올렸고, 2022년 10월부터 이어진 상승 국면을 실적으로 확인해 준 정점 구간의 이벤트였어요.",
  "https://www.asiae.co.kr/en/article/2024043010554876471", "아시아경제")
# ---- 네오팜(092730)
N("092730", "2026-09-08", "+", "earn", "1H26 매출 798억원(+25.5%)·영업이익 185억원(+25%), 사상 최대 기대",
  "네오팜이 2026년 상반기 매출 798억원(전년 대비 +25.5%), 영업이익 185억원(+25%)을 기록했어요. 2025년에도 매출 1,322억원·영업이익 288억원으로 사상 최대였고, 아토팜·리얼베리어·제로이드 성장과 아마존·틱톡샵을 통한 북미 매출 109% 증가가 성장을 이끌었어요. 생산능력도 연 2,150만개에서 2,750만개로 늘려, 2022년 9월부터 이어진 장기 상승이 꾸준한 실적 성장에 기반했다는 점을 보여줘요.",
  "https://en.edaily.co.kr/news/eda202609085425", "이데일리")
# ---- 아이패밀리에스씨(114840)
N("114840", "2025-08-25", "+", "earn", "2Q25 기대 부합·하반기 최대매출 전망 리포트 후 5거래일 +30.6%",
  "DB증권이 8월 18일 아이패밀리에스씨 리포트에서 화장품(롬앤) 부문이 시장 기대에 부합하는 실적을 냈고, 일본 중심에서 동남아·미주·유럽으로 판매가 넓어지며 하반기 사상 최대 매출이 가능하다고 봤어요. 리포트 발표 후 5거래일간 주가가 30.56% 올랐어요. 2025년 7~8월 단기 급등 국면을 해외 채널 확장 기대가 이끌었다는 의미예요.",
  "https://www.fnnews.com/news/202508251949401040", "파이낸셜뉴스")
# ---- 휴메딕스(200670)
N("200670", "2025-05-21", "+", "earn", "1Q25 영업이익 114억원(+7%)·필러수출 +18%에 +7.8% 52주 신고가",
  "휴메딕스의 1분기 매출은 401억원으로 3% 줄었지만 영업이익은 114억원으로 7% 늘었고, 필러 수출이 92억원으로 18% 증가했어요. 브라질 필러 수출 호조와 태국 허가, 중국 NMPA 갱신 정상화 기대에 5월 21일 주가가 7.80% 오른 4만9,050원(장중 4만9,800원, 52주 신고가)으로 3거래일 연속 올랐어요. LS증권은 목표가를 5만7,000원에서 6만2,000원으로 올렸고, 2022년 9월부터 이어진 장기 상승을 필러 수출 성장이 떠받쳤다는 의미예요.",
  "https://www.asiae.co.kr/en/article/2025052109520284546", "아시아경제")
N("214370", "2023-12-28", "-", "cat", "2023 매출 전망 1,500억→800억 하향(-47%), 주가 고점 대비 반토막",
  "케어젠이 12월 28일 2023년 매출 전망치를 연초 제시한 1,500억원에서 800억원으로 47% 낮췄어요. 70~80억원대 매출을 기대한 혈당 건기식 '프로지스테롤'이 1분기 60억원 이후 2분기 9.5억원, 3분기 약 15.2억원에 그쳤고, 회사는 각국 등록 절차 지연에 따른 매출 이연을 이유로 들었어요. 주가는 7월 고점 5만3,400원에서 2만7,000원대로 거의 반토막 났고, 2023년 6월부터 이어진 하락 국면의 핵심 원인이 건기식 기대 붕괴였다는 의미예요.",
  "https://www.smarttoday.co.kr/ko-kr/articles/40675", "스마트투데이")
# ---- 토니모리(214420)
N("214420", "2025-06-23", "+", "earn", "2Q25 영업이익 60억원 전망(컨센 56억원 상회), 한 주간 +34%",
  "유안타증권은 토니모리의 2분기 연결 매출을 629억원(+34%), 영업이익을 60억원(+12%)으로 추정해 시장 기대 56억원을 웃돌 것으로 봤어요. 자회사 메가코스 매출 300억원(+89%), 신규 채널 매출 80억원(+138%), 인도·멕시코·동남아 성장이 동력이었고, 주가는 직전 한 주간 약 34% 올랐어요. 다만 단기 급등이 이어지기 어렵다는 경고도 함께 나와, 2024년 11월부터 이어진 상승 국면의 정점 부근 신호였어요.",
  "https://core.asiae.co.kr/article/2025062307522233030", "아시아경제")
N("216080", "2026-01-10", "-", "cat", "CB 풋옵션 280억원·차입 1,500억원 부담, 주가 6,760원",
  "제테마 주가가 1월 10일 6,760원으로 2021년 2만원대에서 크게 떨어졌어요. 2025년 1~3분기 매출 565억원·영업이익 27억원으로 증권사 연간 추정(영업이익 110억원)에 크게 못 미쳤고, 1월·4월 행사 가능한 전환사채 풋옵션 280억원과 상반기 말 약 1,500억원의 차입금, 유상증자 가능성 소문이 부담으로 꼽혔어요. 회사는 판교 사옥 매각과 톡신 해외 진출로 재무 리스크를 줄이겠다고 했고, 2026년 1월부터 7월까지 이어진 하락 국면의 배경이 재무 부담이었다는 의미예요.",
  "https://www.hankyung.com/article/202512314845i", "한국경제")
# ---- 한국화장품(123690)
N("123690", "2023-08-10", "+", "cat", "중국 단체관광 6년5개월 만에 허용, 상한가(+29.91%)",
  "중국 정부가 2017년 사드 보복 이후 중단했던 자국민의 한국 단체관광을 6년 5개월 만에 허용했어요. 유커 증가 기대에 중국 소비재주로 매수가 몰리며 한국화장품은 8월 10일 29.91% 올라 상한가를 기록했어요. 2023년 7~8월 한 달 새 두 배 가까이 오른 급등이 중국 단체관광 재개 테마였다는 의미예요.",
  "https://www.fnnews.com/news/202308101830171550", "파이낸셜뉴스")
# ---- 하이로닉(149980)
N("149980", "2024-05-16", "+", "earn", "1Q24 매출 79억원(+39.7%)·영업이익 13억원(+58.9%), 수출 +72.7%",
  "하이로닉의 1분기 연결 매출이 79억원으로 전년 대비 39.7%, 영업이익이 13억원으로 58.9% 늘었어요. 수출이 45억원으로 72.7% 늘었고 북미(+2,380%)와 남미(약 10배, 9억원)가 성장을 이끌었으며, 국내에서도 뉴더블로 2.0 매출이 16억원으로 358.8% 늘었어요. 2023년 10월부터 이어진 상승 국면을 해외 매출 확대가 뒷받침했다는 의미예요.",
  "https://www.asiae.co.kr/en/article/2024051608530343878", "아시아경제")
# ---- 라파스(214260)
N("214260", "2023-07-26", "+", "cat", "여드름 마이크로니들 패치 美 FDA cGMP 실사 통과",
  "라파스의 여드름 치료 마이크로니들 패치가 미국 FDA cGMP 실사를 통과했어요. 'Killa ES'는 1월 FDA 등록 후 4월 파트너사 헤이데이를 통해 북미에 출시돼 추가 발주가 들어왔고, 자사 브랜드 'RapMed-2303'도 4분기 북미 출시를 준비 중이었어요. 2022년 12월부터 2023년 7월까지 이어진 상승 국면의 끝자락에 나온 북미 진출 촉매였어요.",
  "https://www.fnnews.com/news/202307260958062634", "파이낸셜뉴스")
# ---- 바이오플러스(099430)
N("099430", "2024-12-16", "+", "earn", "4Q24 HA필러 매출 214억원(+78%) 회복 전망, 2025 고성장 기대",
  "상상인증권은 바이오플러스의 3분기 누적 HA필러 매출이 256억원으로 28% 줄었지만 4분기에는 214억원으로 78% 늘 것으로 봤어요. 상반기 저가 ODM 의존에서 대형 ODM·직영 딜러·지역 거점으로 유통을 재편한 효과가 4분기부터 나타나고, 2024년 연결 매출 628억원·영업이익 213억원을 예상했어요. 2024년 5월부터 2025년 4월까지 이어진 반등 국면이 유통 재편 후 실적 회복 기대에 기댔다는 의미예요.",
  "https://www.asiae.co.kr/en/article/2024121607520586161", "아시아경제")
N("214420", "2026-08-24", "-", "earn", "1H26 매출 1,060억원(-4.9%)·영업이익 64억원(-30.3%) 부진",
  "토니모리의 2026년 상반기 매출은 1,060억원으로 4.9%, 영업이익은 64억원으로 30.3% 줄었어요. 해외 매출이 287억원(+20.9%)으로 늘었지만 비중이 27%에 그쳐 내수 의존이 컸고, 기초화장품 비중이 약 70%라 달바·토리든 등 비건 스킨케어와 경쟁이 심해졌으며 해외 바이어의 보수적 재고 운영으로 일부 주문이 하반기로 밀렸어요. 2025년 6월 고점 이후 이어진 하락 국면이 실적 역성장으로 굳어졌다는 의미예요.",
  "https://news.tf.co.kr/read/economy/2357252.htm", "더팩트")
N("114840", "2026-09-23", "-", "earn", "1H26 영업이익 105억원(-26.7%), 52주 고점 대비 -67.8%",
  "아이패밀리에스씨 주가는 9월 18일 8,510원으로 52주 최고가 2만6,400원보다 67.8% 낮았어요. 2025년 매출은 2,241억원(+9.4%)으로 늘었지만 영업이익은 271억원(-19.3%)으로 줄었고, 2026년 상반기도 매출 1,135억원(+1.3%)에 영업이익 105억원(-26.65%)으로 부진했어요. 글로벌 마케팅·유통 확대로 판관비가 2024년 396억원에서 2025년 611억원으로 불어나고 미국 법인이 자본잠식에 빠졌으며, DB증권이 목표가를 1만2,000원으로 내려 2025년 8월 이후 하락 국면의 원인이 수익성 악화였다는 의미예요.",
  "https://dealsite.co.kr/articles/169332", "딜사이트")
N("199550", "2026-02-19", "-", "earn", "2025 매출 257억원(-22.2%)·영업손실 115억원, 美 소송에 북미 매출 -87%",
  "레이저옵텍의 2025년 잠정 매출은 257억원으로 22.2% 줄고 영업손실이 115억원으로 크게 불어났어요. 2024년 7월 경쟁사 스트라타 스킨 사이언스가 팔라스 레이저 마케팅·CPT 코드 청구 문제로 미국 펜실베이니아 동부 연방법원에 소송을 내면서 북미 매출이 약 59억원에서 2025년 3분기 누적 약 7억원으로 87% 급감했고, 소송비도 3억원에서 33억원으로 늘었어요. 2026년 1월 법원이 일부 청구만 기각하고 나머지는 본안으로 넘겨, 2025년 3월부터 이어진 하락 국면의 핵심이 미국 소송 리스크였다는 의미예요.",
  "https://www.ibtomato.com/View.aspx?no=17461&type=1", "IB토마토")
N("099430", "2026-01-06", "-", "news", "신공장 고정비·인건비 부담, 영업이익률 43.2%→35.7%",
  "바이오플러스의 영업이익은 2023년 약 280억원에서 2024년 237억원으로 줄고 영업이익률도 43.2%에서 35.7%로 낮아졌어요. 2025년 3분기 누적 급여가 49.3억원으로 전년 대비 두 배 넘게 늘었고, 음성 신공장 감가상각비가 약 8.5억원으로 두 배가 됐으며, 공장 건설로 부채가 2023년 말 347.5억원에서 1,044억원으로 불어나 이자 부담도 커졌어요. 가동률이 천천히 오를 것이란 전망 속에 2025년 4월 이후 하락 국면이 신공장 비용 부담 속 성장통에 따른 것이었다는 의미예요.",
  "https://medicaltimes.com/Mobile/News/NewsView.html?ID=1166716", "메디칼타임즈")
