# ---- 삼양식품(003230)
N("003230", "2024-05-17", "+", "earn", "1분기 영업익 801억(+235.8%), 컨센서스 424억의 약 2배·상한가",
  "삼양식품은 1분기 연결 매출 3857억원(+57.1%), 영업이익 801억원(+235.8%)을 냈는데, 시장 전망치 424억원의 두 배 가까운 수치였어요. 5월 17일 주가는 29.99% 오른 44만6500원으로 상한가를 기록하며 6거래일 연속 상승·52주 신고가를 경신했어요. 불닭 수출 호조가 숫자로 확인되면서 장기 상승 국면이 한 단계 도약한 계기였어요.",
  "https://v.daum.net/v/20240518055700642", "매일경제")
# ---- 보해양조(000890)
N("000890", "2023-09-18", "-", "news", "2분기 영업손실 26억·주가 541원, 잎새주 점유율 50%대로",
  "보해양조는 2023년 2분기 영업손실 26억원, 순손실 27억원을 냈고 분기 매출은 300억원대 근처에서 200억원대 초반으로 줄었어요. 호남 점유율 90% 이상이던 잎새주가 대형사 공세에 50%대로 밀리고 후속 과실주도 흥행하지 못했으며, 주가는 2021년 10월 27일 이후 1000원을 회복하지 못한 채 9월 15일 541원에 머물렀어요. 테마성 급등 후 되돌림이 반복되는 가운데 본업 경쟁력 약화가 장기 하락의 바탕이었어요.",
  "https://news.tf.co.kr/read/ogmeta/2043823.htm", "더팩트")
# ---- 하림지주(003380)
N("003380", "2025-12-11", "+", "cat", "양재 물류단지 개발 기대에 장중 +14.4%",
  "12월 11일 하림지주는 서울 대형 터미널 개발 이슈가 부각되며 장중 14.43% 오른 1만150원에 거래됐어요. 자회사 하림산업이 추진하는 양재화물터미널 부지 복합개발(지하 8층~지상 59층 물류·주거·업무)이 8월 서울시 최종 승인을 받았고, 내년 하반기 착공이 전망됐어요. 장기간 지연되던 양재 개발 가시화가 2025년 반등 국면의 핵심 재료였어요.",
  "https://view.asiae.co.kr/article/2025121109362638659", "아시아경제")
# ---- 사조대림(003960)
N("003960", "2024-06-17", "+", "cat", "냉동김밥 미국 수출 소식에 장중 +23.7%",
  "사조대림은 6월 14일 참치김밥 등 냉동김밥 3종을 매달 7만2000줄씩 미국 H마트에 수출한다고 발표했어요. 6월 17일 주가는 장중 23.70% 오른 7만6200원에 거래됐어요. K-푸드 수출 테마에 올라타며 장기 상승 국면이 고점으로 치달은 마지막 촉매였어요.",
  "https://view.asiae.co.kr/article/2024061714092795203", "아시아경제")
# ---- 남양유업(003920)
N("003920", "2024-01-04", "+", "cat", "대법원 한앤코 승소 확정, 판결 전후 2주간 주가 약 +30%",
  "대법원은 1월 4일 한앤컴퍼니가 홍원식 회장 일가를 상대로 낸 주식양도 소송에서 한앤코 손을 들어주며 오너 일가 지분 53.08%의 매각을 확정했어요. 선고일이 잡힌 뒤 약 2주 사이 주가는 30% 가까이 올랐고 1월 5일 종가는 60만5000원이었어요. 3년 가까이 이어진 경영권 분쟁이 끝나고 지배구조 개선 기대가 커진 것이 상승 국면의 핵심 동력이었어요.",
  "https://news.mtn.co.kr/news-detail/2024010915481360990", "머니투데이방송")
# ---- 빙그레(005180)
N("005180", "2024-05-17", "+", "earn", "1분기 영업익 211억(+65.2%) 기대 상회, 장중 +20.1%·9년 만 최고가",
  "빙그레는 1분기 연결 영업이익이 211억원으로 1년 전보다 65.2% 늘었다고 발표했고, 증권가는 시장 기대를 웃돈 성장세로 평가했어요. 5월 17일 주가는 장중 최대 20.1% 올라 9만800원을 찍으며 2015년 5월 이후 9년 만의 최고가를 기록했어요. 바나나맛우유·메로나 수출 성장이 실적으로 확인되며 상승 국면을 가속한 계기였어요.",
  "https://biz.sbs.co.kr/amp/article/20000171887", "SBS Biz")
N("005180", "2025-01-13", "+", "cat", "지주사 전환·자사주 10.25% 소각 계획, 한 달 +16.7%",
  "빙그레는 2024년 11월 지주사 전환과 인적분할(2025년 5월 1일 효력)을 발표하고 분할 전 자사주 10.25%를 전량 소각하기로 했어요. 1월 13일 종가는 8만5100원(+4.67%)으로 한 달 새 약 16.7%, 2024년 9월 9일 저점 5만9200원 대비 약 43.8% 올랐고, 4분기 영업손실이 컨센서스(-72억원)보다 작은 -24억원 수준일 것이란 전망도 나왔어요. 주주환원과 수출 성장 기대가 겹친 것이 2024년 말~2025년 초 반등 국면의 배경이었어요.",
  "https://www.hankyung.com/article/2025011438866", "한국경제")
# ---- 하이트진로(000080)
N("000080", "2023-08-16", "-", "earn", "켈리 출시 첫 분기 영업익 119억(-80.9%), 광고비 +50.2%",
  "하이트진로의 2023년 2분기 연결 매출은 6415억원(-0.97%)에 그쳤고 영업이익은 119억원으로 1년 전보다 80.9% 급감했어요. 4월 출시한 맥주 켈리 마케팅에 광고선전비가 784억원(+50.2%)으로 늘어 매출 대비 12.2%까지 올라갔지만 맥주 매출 증가는 3.8%에 그쳤어요. 신제품 비용 부담이 이익을 깎아낸 것이 장기 하락 국면에서 실적 기대를 꺾은 사건이었어요.",
  "https://www.etoday.co.kr/news/view/2275196", "이투데이")
# ---- 대상(001680)
N("001680", "2023-07-10", "-", "earn", "2분기 영업익 232억(-52.3%) 전망, 주가 1만6480원 바닥권",
  "하나증권은 대상의 2분기 연결 영업이익이 232억원으로 52.3% 줄 것으로 내다봤는데, 라이신 시황 악화와 옥수수 원가 부담으로 소재 부문이 적자를 이어간 탓이었어요. 7월 7일 종가는 1만6480원으로 목표가 3만3000원의 절반 수준이었고, 하반기에는 아미노산 기저 부담 해소와 전분당 스프레드 개선으로 이익 증가가 가능하다는 전망이 함께 나왔어요. 소재 부진이 2021년부터 이어진 하락 국면의 바닥을 만들고, 이후 반등의 출발점이 된 시점이에요.",
  "https://news.tf.co.kr/read/ogmeta/2029356.htm", "더팩트")
# ---- 한성기업(003680)
N("003680", "2026-07-09", "+", "cat", "상장폐지 위기에 '돈쭐' 매수 운동, 상한가 6510원(+29.94%)",
  "한국거래소가 7월부터 코스피 상장폐지 시가총액 기준을 200억원에서 300억원으로 올리면서, 6월 시총이 약 261억원까지 떨어진 한성기업이 퇴출 위기에 놓였다는 소식이 퍼졌어요. 온라인에서 제품 구매·소액 주식 매수 응원 운동이 번지며 7월 9일 주가는 1500원(29.94%) 오른 6510원으로 상한가를 기록했고 시총은 300억원 안팎으로 회복했어요. 2025년 영업이익이 110억원에서 58억원으로 줄어든 실적 부진 속에서, 테마성 매수가 2026년 6~7월 급반등 국면을 만든 사건이에요.",
  "https://magazine.hankyung.com/business/article/202607081986b", "한경비즈니스")
# ---- SPC삼립(005610)
N("005610", "2026-06-18", "-", "news", "시화공장 사고·화재 여파, 2025년 영업이익률 1.1%로 하락",
  "SPC삼립은 2025년 5월 시화공장 안전사고에 이어 2026년 2월 화재로 해당 공장 가동이 중단됐어요. 인건비·고정비 증가와 화재 재고손실로 2025년 영업이익률은 1.1%로 2024년 2.8%보다 1.7%p 떨어졌어요. 잇단 공장 사고가 수익성을 훼손한 것이 2025년 4월 이후 하락 국면의 핵심 배경이에요.",
  "https://newstomato.com/ReadNews.aspx?no=1304472", "IB토마토")
