N("001800", "2025-10-20", "+", "news", "IBK, 바이오 성과 주목하며 목표가 2.1만→2.8만원(+33%)",
  "IBK투자증권은 오리온홀딩스의 바이오 사업 성과에 주목하며 목표주가를 2만1000원에서 2만8000원으로 올렸어요. 오리온바이오로직스의 시린이 치료제가 미국 임상 2b상을 진행 중이고, 중국 대장암 진단키트 합작법인이 품목허가를 신청했으며, 그룹은 리가켐바이오의 최대주주이기도 해요. 제과 지주사에 바이오 가치가 더해진 점이 장기 상승 국면의 재평가 논리였어요.",
  "https://www.smarttoday.co.kr/ko-kr/articles/93971", "스마트투데이")
