# ---- 대상(001680) 하락 국면
N("001680", "2026-06-01", "-", "earn", "1분기 매출 1조(-2%)·영업익 570억 정체, 바이오·인니 부진",
  "교보증권은 대상의 2026년 1분기 연결 매출이 약 1조원으로 2% 줄고 영업이익은 570억원으로 1년 전과 비슷한 수준에 머물렀다고 분석했어요. 바이오 부문은 환율 효과에도 판가 하락이 부담이었고, 전분당은 수요 감소와 판가 하락으로 부진했으며, 인니 부문 영업이익은 53% 줄었어요. 5월 29일 종가는 1만9250원으로 목표가 3만4000원과 큰 격차를 보였고, 바이오 턴어라운드가 확인되지 않은 것이 2024년 6월 이후 하락 국면이 이어진 이유였어요.",
  "https://www.sidae.com/article/2026060108400633190", "시대")
# ---- 동원산업(006040)
N("006040", "2022-04-13", "-", "cat", "동원엔터 합병비율 1:3.84 논란, 발표 후 주가 -12%",
  "동원산업은 4월 7일 지주사 동원엔터프라이즈와 1대 3.84 비율로 합병한다고 발표했고, 합병가액은 동원산업 주당 24만8961원·엔터프라이즈 19만1130원으로 정해졌어요. 소액주주들은 동원산업이 순익 대비 지나치게 저평가돼 김남정 부회장 등 대주주 우호 지분이 86%로 늘어난다며 반발했고, 주가는 발표일 대비 12% 넘게 빠졌어요. 지배구조 개편 과정의 소액주주 가치 훼손 우려가 2021~2023년 하락 국면을 이끈 회사 고유 악재였어요.",
  "https://biz.sbs.co.kr/amp/article/20000058314", "SBS Biz")
N("006040", "2024-11-27", "+", "cat", "밸류업 계획: 반기배당·배당성향 30%·PBR 1배 목표",
  "동원산업은 11월 27일 2025년부터 연 2회 반기배당을 하고 배당성향을 지난해 17.6%에서 30%까지 높이겠다는 밸류업 계획을 발표했어요. 총주주수익률 40%, ROE 15% 이상, PBR 0.44배에서 1배 이상을 목표로 내걸었고, 적은 유통주식 수를 늘리려 무상증자·주식배당도 이어가겠다고 했어요. 저PBR 해소를 위한 구체적 주주환원 약속이 2023~2025년 상승 국면을 뒷받침한 회사 고유 촉매였어요.",
  "https://www.smarttoday.co.kr/ko-kr/articles/65528", "스마트투데이")
# ---- 사조산업(007160)
N("007160", "2024-07-08", "+", "cat", "사조대림 목표가 16만원 리포트에 사조그룹주 동반 급등, 사조산업 +23%",
  "하나증권이 사조대림에 목표주가 16만원의 매수 보고서를 내자 7월 8일 사조그룹주가 줄줄이 급등했고 사조산업도 장중 23% 넘게 올랐어요. 보고서는 사조대림의 연간 이익 체력이 2000억원인데 시가총액은 7000억원뿐이고 2024년 영업이익이 1918억원(+49%)에 이를 것으로 봤어요. K푸드·냉동김밥 수출 기대로 6월부터 시작된 그룹주 재평가가 사조산업 상승 국면의 정점 구간을 만들었어요.",
  "https://www.smarttoday.co.kr/ko-kr/articles/54508", "스마트투데이")
# ---- CJ씨푸드(011150)
N("011150", "2024-06-05", "-", "news", "김 테마 열기 식으며 6거래일 연속 하락, 5320원→4155원",
  "김 수출 증가·가격 인상으로 급등했던 '검은 반도체' 김 관련주인 CJ씨푸드가 6월 5일 3.26% 내린 4155원에 거래되며 6거래일 연속 하락했어요. 5월 말 5320원에서 4100원대로 내려왔고, 외국인과 기관의 순매도가 하락을 이끌었다고 기사는 짚었어요. 김 테마로 쌓은 상승분이 빠지기 시작한 시점으로, 2024년 6월 이후 장기 하락 국면의 출발점이었어요.",
  "https://www.asiae.co.kr/en/article/2024060510504467375", "아시아경제")
N("011150", "2024-05-24", "+", "cat", "K김밥 인기에 김 대장주로 +16%, 52주 신고가 4965원",
  "미국 등에서 냉동김밥 인기가 커지며 김 수요가 늘자 CJ씨푸드는 5월 24일 장 초반 16% 오른 4820원에 거래되고 장중 4965원으로 52주 신고가를 썼어요. 거래량은 1009만주로 전날의 9배가 넘었고, 지난해 12월 삼해상사 지분 100% 인수 후 1분기 김 수출 매출이 47억원으로 225% 늘었어요. 김 테마의 대장주로 묶이면서 2023년 10월~2024년 6월 상승 국면의 막바지 급등을 만든 사건이에요.",
  "https://www.asiae.co.kr/en/article/2024052409354820445", "아시아경제")
N("011150", "2024-08-13", "-", "earn", "김 수출 호황에도 2분기 영업손실 1.7억 적자전환, 주가 -6%",
  "CJ씨푸드는 2024년 2분기 매출이 474억9700만원으로 40.5% 늘었지만 영업이익은 1억7100만원 손실로 1년 전 1억9300만원 흑자에서 적자 전환했어요. 실적 발표 뒤 주가는 실망 매물에 6% 넘게 떨어져 3800원 안팎까지 밀렸고, 6월 중순 고점 6490원 대비 약 40% 낮아졌어요. 김 테마 기대가 실제 이익으로 이어지지 않는다는 점이 확인되며 2024년 6월 이후 하락 국면이 굳어졌어요.",
  "https://www.smarttoday.co.kr/ko-kr/articles/57300", "스마트투데이")
# ---- 사조씨푸드(014710)
N("014710", "2024-05-24", "+", "cat", "K김밥발 김 테마 편입, 하루 +14.8%",
  "냉동김밥 해외 인기로 김 관련주가 들썩인 5월 24일 사조씨푸드는 장 초반 14.8% 오른 4850원 안팎에 거래됐고 거래량은 148만주로 전날의 3배를 넘었어요. 1분기 김 부문 매출이 85억원으로 전체의 20.2%를 차지해 김 수혜주로 분류됐어요. 김 테마 편입이 2024년 4~9월 +133% 상승 국면을 이끈 핵심 동력이었어요.",
  "https://www.asiae.co.kr/en/article/2024052409354820445", "아시아경제")
# ---- 풀무원(017810)
N("017810", "2025-02-04", "+", "earn", "2024년 매출 3.21조(+7.4%)·영업익 921억(+48.6%) 발표에 +5.4%",
  "풀무원은 2024년 매출 3조2137억원(+7.4%)으로 처음 3조원을 넘고 영업이익 921억원(+48.6%), 순이익 340억원(+154.7%)을 냈다고 밝혔어요. 미국 법인이 이끄는 해외 사업 성장(두부 +12.1%, 아시안누들 +21.1%)이 두드러졌고, 2월 4일 주가는 5.38% 오른 1만770원을 기록했어요. 해외 사업 흑자 전환 기대를 실적으로 확인시키며 2025년 1~2월 급등 국면의 정점을 만든 발표였어요.",
  "https://www.asiae.co.kr/en/article/2025020409335422863", "아시아경제")
N("017810", "2023-08-27", "+", "earn", "2분기 영업익 168억(+6.8%)·미국 매출 +22%, 리포트 후 이틀 새 +12%",
  "풀무원은 2023년 2분기 매출 7554억원(+7%), 영업이익 168억원(+6.8%)을 냈고 미국 매출이 881억원으로 22% 늘며 미국 법인 적자가 절반 이상 줄었어요. DS투자증권이 8월 24일 미국 두부 점유율 1위와 K푸드 성장을 근거로 목표가 1만4000원의 매수 리포트를 내자 주가는 이틀 만에 12.06% 올랐어요. 미국 법인 턴어라운드 기대가 2023년 7월~2024년 6월 상승 국면의 출발을 이끌었어요.",
  "https://www.mt.co.kr/stock/2023/08/27/2023082711093219643", "머니투데이")
# ---- KT&G(033780)
N("033780", "2025-07-23", "+", "cat", "자사주 3600억 매입·배당성향 50%+에 사상 최고가 14만4000원",
  "KT&G 주가는 7월 14일 14만4000원으로 사상 최고가를 찍어 올해 저점 8만7300원에서 크게 올랐어요. 1분기에만 발행주식의 2.5%인 3600억원어치 자사주를 사들였고 하반기에도 비슷한 규모를 예고했으며, 배당성향은 50%를 넘겼어요. 1분기 해외 판매량·매출·영업이익이 각각 23%·54%·312% 늘어난 궐련 수출 성장과 공격적 주주환원이 2020년 이후 장기 상승 국면을 이끈 핵심 동력이었어요.",
  "https://www.koreatimes.co.kr/amp/business/companies/20250723/ktg-hits-record-stock-high-on-shareholder-friendly-moves-stronger-tobacco-business", "코리아타임스")
# ---- 마니커(027740)
N("027740", "2022-05-24", "+", "cat", "말레이시아 닭고기 수출 중단 테마에 장중 +20%, 2255원",
  "말레이시아가 6월부터 월 360만 마리 규모의 닭고기 수출을 중단한다고 발표하자 5월 24일 마니커는 장중 20% 넘게 올라 2255원까지 치솟았고, 오전 10시 반 16.71% 오른 2025원에 거래됐어요. 하림·마니커에프앤지 등 닭고기주가 함께 급등했지만 회사 실적이 아닌 해외 공급 이슈에 기댄 테마성 상승이었어요. 이 테마 급등이 고점이 됐고, 이후 열기가 식으며 2026년까지 -75% 장기 하락 국면이 시작됐어요.",
  "https://economist.co.kr/article/view/ecn202205240030", "이코노미스트")
# ---- CJ프레시웨이(051500)
N("051500", "2025-03-20", "+", "earn", "1분기 영업익 111억(+5.7%) 전망·성장 재개 기대에 +6.5%",
  "IBK투자증권이 CJ프레시웨이의 1분기 매출을 7803억원(+6.7%), 영업이익을 111억원(+5.7%)으로 내다보며 지난해 4분기부터 시작된 성장세가 이어질 것으로 보자 3월 20일 주가는 6.54% 오른 2만2000원에 거래됐어요. 외식 경기 부진 속에서도 프랜차이즈 매출 증가와 C&D 모델 전환으로 2분기 성수기에 성장 폭이 커질 것이란 분석이었어요. 실적 저점 통과 기대가 2024년 12월~2026년 2월 +91% 상승 국면을 이끈 배경이에요.",
  "https://www.asiae.co.kr/en/article/2025032009475791542", "아시아경제")
# ---- 무학(033920)
N("033920", "2024-12-10", "+", "earn", "3분기 누적 영업익 127억(+6%)·영업현금흐름 5배, '부산갈매기' 흥행",
  "무학은 2024년 3분기 누적 매출 1149억원(+2.96%), 영업이익 127억원(전년 120억원)을 냈고 3분기 영업활동현금흐름은 100억원으로 1년 전 22억원의 5배 가까이 늘었어요. 3월 출시한 지역 한정 소주 '좋은데이 부산갈매기'가 매출 호조를 이끌어 2분기 매출이 402억원(+8.36%)으로 늘었어요. 2021년 영업손실 9억원에서 2022~2023년 156억~162억원 흑자로 돌아선 뒤 이익이 안정된 흐름이 2022년 10월 이후 상승 국면의 바탕이었어요.",
  "https://newstomato.com/ReadNews.aspx?no=1247320", "IB토마토")
# ---- 오뚜기(007310)
N("007310", "2025-08-18", "-", "earn", "2분기 영업익 451억(-26.8%) 기대 하회, 목표가 60만→55만원",
  "오뚜기는 2025년 2분기 매출 9020억원(+5%)에 영업이익이 451억원으로 26.8% 줄어 시장 기대에 못 미쳤어요. 내수 식품 소비 부진과 인건비·원가 부담이 마진을 깎았고, iM증권은 목표주가를 60만원에서 55만원으로 내렸어요. 해외 비중이 높은 경쟁사와 달리 내수 의존 구조에서 이익이 뒷걸음질한 것이 2018년 이후 장기 하락 국면이 이어진 회사 고유 원인이에요.",
  "https://www.asiae.co.kr/en/article/2025081807560077187", "아시아경제")
N("051500", "2024-11-08", "-", "earn", "3분기 영업익 282억(-6.6%), 외식 경기 침체 직격",
  "CJ프레시웨이는 2024년 3분기 매출 8319억원(+2.8%)에 영업이익 282억원으로 6.6% 줄었다고 11월 8일 발표했어요. 회사는 장기화된 외식 시장 침체와 고물가로 물량이 늘어도 이익이 줄었다고 설명했어요. 매출 3조원대에도 수익성이 꺾인 흐름이 2022년 4월~2024년 12월 하락 국면의 마지막 구간을 만든 실적이었어요.",
  "https://www.asiae.co.kr/en/article/2024110816091952996", "아시아경제")
# ---- 사조동아원(008040)
N("008040", "2026-06-24", "-", "cat", "주가 772원 동전주, 동전주 상폐 규정 앞두고 10대1 주식병합 결정",
  "사조동아원은 6월 22일 액면가를 500원에서 5000원으로 올리는 10대 1 주식병합을 공시했어요. 6월 23일 종가가 772원으로 7월 1일 시행되는 '1000원 미만 30거래일 지속 시 관리종목 지정' 기준 아래에 있었고, 시가총액은 약 1120억원에 그쳤어요. 사조그룹 상장사 중 유일한 동전주로 전락한 상황을 보여주는 공시로, 2025년 9월 이후 하락 국면 속 저가주 이미지와 상장 유지 우려를 드러냈어요.",
  "https://v.daum.net/v/20260624134342786", "다음 뉴스")
N("017810", "2026-05-14", "-", "earn", "2025년 해외 영업손실 163억(3배 확대)·신종자본증권 등급 BBB+→BBB",
  "풀무원의 2025년 해외 매출은 6669억원으로 5% 늘었지만 해외 영업손실은 163억원으로 전년 55억원의 약 3배로 커졌고 해외 영업이익률은 -0.9%에서 -2.4%로 나빠졌어요. 한국신용평가는 신종자본증권 등급을 BBB+에서 BBB로 낮췄고, 신종자본증권 잔액은 2020년 말 2530억원에서 2025년 말 3985억원으로 불었어요. 2025년 초 급등의 근거였던 해외 흑자 전환 기대가 꺾이고 재무 부담이 부각된 것이 2025년 2월 이후 하락 국면의 회사 고유 원인이에요.",
  "https://newstomato.com/ReadNews.aspx?no=1300687", "IB토마토")
# ---- 국순당(043650)
N("043650", "2025-03-31", "-", "earn", "2024년 영업적자 23억, 5년 만의 적자전환·판관비 +22.8%",
  "국순당은 2024년 매출 688억원(-2.36%)에 영업손실 23억원을 내 2019년 이후 5년 만에 적자로 돌아섰어요. 백세주 리브랜딩·팝업 레스토랑 등 마케팅으로 광고선전비가 22억원에서 47억원으로 두 배가 되며 판관비가 267억원에서 328억원으로 22.84% 늘었지만 약주 매출은 7.61% 줄었어요. 외형 성장 투자가 실적 악화로 끝난 것이 2024년 6월 이후 하락 국면을 이끈 회사 고유 원인이에요.",
  "https://www.ibtomato.com/View.aspx?no=14632&type=1", "IB토마토")
# ---- 우양(103840)
N("103840", "2024-06-10", "+", "cat", "냉동김밥 美 대형마트 수출에 한 달 +112%",
  "7월부터 냉동김밥을 미국 대형마트에 수출한다는 소식에 5월 7일~6월 7일 한 달간 주가가 약 112% 올랐고, 6월 7일엔 상한가(9,030원)로 마감했어요. 국내 냉동김밥 수출액이 4월 약 605만 달러로 전년 대비 531.5% 급증했고, 증권가는 올해 영업이익 100억원(2023년 13억원)으로 흑자 전환을 전망했어요. 국내 냉동김밥 생산업체 중 유일한 상장사라는 점이 '제2의 삼양식품' 테마로 묶이며 상승 국면의 정점을 만든 재료였어요.",
  "https://v.daum.net/v/20240610111850036", "조선비즈")
# ---- 에스앤디(260970)
N("260970", "2024-06-16", "+", "cat", "불닭 소스 원료 독점 공급 부각에 상한가",
  "KB증권이 에스앤디가 삼양식품 불닭 시리즈 소스의 핵심 원료를 독점 공급한다는 리포트를 내자 6월 13일 상한가, 14일에도 약 20% 더 올랐어요. 2024년 1분기 매출은 238억원(+30%), 영업이익은 35억원(+72%)으로 영업이익률이 11%에서 14%로 올랐어요. '불닭 수혜주'로 재평가되면서 2023년 10월 이후 상승 국면이 본격적으로 가속된 계기였어요.",
  "https://v.daum.net/v/20240616163448121", "머니투데이")
# ---- CJ제일제당(097950)
N("097950", "2025-04-09", "-", "earn", "1분기 영업익 컨센서스 -10.9% 전망에 52주 신저가",
  "한국투자증권이 1분기 매출 7조3416억원(컨센서스 -1.2%), 영업이익 3484억원(전년 대비 -7.3%, 컨센서스 -10.9%)으로 기대에 못 미칠 것으로 내다보면서 주가가 3거래일 연속 하락했어요. 4월 9일 장중 23만원까지 내려가 52주 신저가를 새로 썼어요. 실적 눈높이가 계속 낮아지며 2024년 7월 이후 하락 국면이 이어진 대표 장면이에요.",
  "https://www.asiae.co.kr/en/article/2025040909325044578", "아시아경제")
N("097950", "2024-02-14", "+", "earn", "4Q23 영업익 2983억원 컨센서스 부합, 저기저 반등 기대",
  "2023년 4분기 매출 7조2894억원, 영업이익 2983억원으로 시장 컨센서스에 부합했고, CJ대한통운을 뺀 기준 영업이익은 전년 대비 28% 늘었어요. NH투자증권은 낮은 기저 덕분에 2024년 연결 영업이익 반등의 가시성이 높다며 목표가 43만원, 매수 의견을 유지했어요(2월 13일 종가 29만8000원). 2023년 바닥을 지나 이익 회복 기대가 자리잡으며 상승 국면을 뒷받침한 실적이었어요.",
  "https://www.asiae.co.kr/en/article/2024021408265869735", "아시아경제")
N("097950", "2024-12-03", "+", "cat", "바이오사업부 매각설에 11/15→11/20 +15%",
  "바이오사업부(매각가 5조~6조원 거론) 매각설이 나오자 주가가 11월 15일 24만6500원에서 11월 20일 28만4500원으로 약 15% 올랐다가 일부를 반납했어요. 바이오사업부 영업이익은 2022년 4106억원에서 2023년 804억원으로 80.4% 급감한 상태였고, 중국 업체의 저가 공세 탓에 매각가 6조원에 회의적인 시각도 있었어요. 하락 국면 중 일시적인 반등 재료였지만 추세를 되돌리진 못했어요.",
  "https://v.daum.net/v/20241203210351665", "매경이코노미")
N("103840", "2025-08-18", "+", "earn", "2Q25 영업익 9.6억원 +152%, 하반기 유럽 코스트코 수출",
  "2분기 연결 매출 453억원(+3.9%), 영업이익 9억6000만원(+151.7%)을 발표했어요. 하반기에 영국·유럽 코스트코로 핫도그 수출을 시작하고 매출 증가로 하반기 영업이익률이 개선될 것이라고 밝혔어요. 2025년 6~8월 반등 국면의 끝자락에서 실적 개선 기대를 확인한 재료였어요.",
  "https://view.asiae.co.kr/en/article/2025081809554538204", "아시아경제")
N("260970", "2025-07-14", "-", "cat", "삼양식품 소스업체 지앤에프 인수설에 장중 -19.7%",
  "7월 11일 삼양식품이 불닭볶음면 소스 원료 공급업체 지앤에프 지분 100%를 약 600억원에 인수한다는 소식이 전해지자, 7월 14일 에스앤디 주가는 장 초반 19.67% 떨어진 10만5800원까지 밀렸어요. 핵심 고객사가 소스 공급망을 내재화할 수 있다는 우려가 투자심리를 꺾었어요. 불닭 독점 공급사라는 상승 논리가 흔들리며 2025년 6월 고점 이후 하락 국면을 연 사건이었어요.",
  "https://www.ajunews.com/view/20250714095618167", "아주경제")
# ---- 선진(136490)
N("136490", "2025-07-17", "+", "earn", "올해 영업익 1595억원 +28.6% 전망·PER 2배 부각에 +13.8%",
  "7월 17일 장중 주가가 13.84% 오른 1만4810원을 기록했고, 1분기 실적 발표 이후 주가가 두 배 넘게 올랐어요. 유진투자증권은 곡물가 하락과 2분기 환율 6.7% 하락으로 본업 마진이 좋아져 올해 매출 1조8000억원(+6.3%), 영업이익 1595억원(+28.6%), 순이익 1580억원을 낼 것으로 봤고, 이는 PER 약 2배 수준이에요. 이익 급증에 비해 극단적으로 저평가됐다는 인식이 2025년 3~7월 +145% 상승 국면을 이끌었어요.",
  "https://www.asiae.co.kr/en/article/2025071713540154019", "아시아경제")
# ---- 해태제과식품(101530)
N("101530", "2024-06-21", "+", "news", "이른 폭염에 빙과주 강세, 6월 +34.9%·6/10 상한가",
  "6월 10일 작년보다 일주일 빠른 첫 폭염주의보가 내려지자 해태제과식품은 상한가로 마감했고, 6월 들어 21일까지 주가가 34.91% 올랐어요. 증권가는 원유 수입가 안정 등으로 원가율이 낮아지고 여름 성수기 효과가 앞당겨져 2분기 빙과 업체 실적이 크게 좋아질 것으로 봤어요. 2023년 10월 이후 상승 국면의 막바지 급등을 만든 재료였어요.",
  "https://mobile.newsis.com/view/NISX20240621_0002781502", "뉴시스")
# ---- 롯데웰푸드(280360)
N("280360", "2024-06-21", "+", "news", "폭염 수혜·목표가 23만원 상향에 6월 +30.6%",
  "이른 폭염으로 빙과 수혜 기대가 커지며 롯데웰푸드 주가는 5월 말 14만4000원에서 6월 21일 18만8000원으로 30.56% 올랐고, 6월 10일 하루에만 12.17% 뛰었어요. 한국투자증권은 2분기 빙과 판매량 증가와 인도 빙과 사업 여건 호조, 추가 실적 상향 가능성을 들어 목표가를 18만원에서 23만원으로 올렸어요. 2023년 7월 이후 +93% 상승 국면의 정점 부근에서 나온 급등이었어요.",
  "https://mobile.newsis.com/view/NISX20240621_0002781502", "뉴시스")
# ---- 이지바이오(353810)
N("353810", "2025-11-28", "+", "earn", "3Q25 영업익 112억원 +38.7%, 연초 대비 +63.9% 신고가",
  "3분기 매출 1169억원, 영업이익 112억원(+38.7%)을 냈고, 3분기 누적 영업이익은 314억원(+32.8%)이었어요. 지난해 인수한 미국 사료업체 데브니쉬 뉴트리션의 영업이익률이 4%대에서 6%로 오르고 곡물가 하락으로 사료첨가제 구매력이 좋아진 덕분이에요. 주가는 52주 신고가를 다시 쓰며 올해 63.9% 올랐고(유진투자증권 목표가 1만원 유지), 2023년 10월 이후 상승 국면의 실적 근거가 됐어요.",
  "https://core.asiae.co.kr/article/2025112716045725026", "아시아경제")
# ---- 현대그린푸드(453340)
N("453340", "2025-05-21", "+", "earn", "런치플레이션에 1Q25 영업익 322억원, 4일 연속 신고가 +12.3%",
  "1분기 매출 5706억원(+2%), 영업이익 322억원(+3.2%)으로 영업일수가 적은 분기에도 이익을 지켜냈어요. 외식 점심값이 1만원을 넘자 구내식당 이용이 늘어난 '런치플레이션' 효과로 단체급식 부문이 좋아졌고, 주가는 5월 15일부터 4거래일 연속 신고가를 쓰며 12.27% 올라 20일 1만7390원(장중 1만7440원)을 기록했어요. 연기금 중심 기관 순매수가 이어지며 2023년 9월 이후 상승 국면을 이끈 실적 재료였어요.",
  "https://www.hankyung.com/article/2025052055246", "한국경제")
# ---- 오리온(271560)
N("271560", "2023-05-15", "-", "earn", "1Q23 영업익 991억원 -8.7%, 중국 매출 -13.5%",
  "1분기 연결 매출은 6638억원(+1.6%)이었지만 영업이익은 991억원으로 8.7% 줄었어요. 주력인 중국 법인 매출이 2642억원(-13.5%), 영업이익이 383억원(-22.6%)으로 꺾였고 중국 매출 비중은 46.4%에서 39.7%로 낮아졌어요. 회사는 춘절이 열흘가량 빨랐던 탓이라고 했지만, 중국 성장 둔화 우려가 커지며 2023년 4월 이후 하락 국면이 시작된 계기였어요.",
  "https://greened.kr/news/articleView.html?idxno=303306", "녹색경제신문")
N("280360", "2025-05-09", "-", "earn", "1Q25 영업익 164억원 -56.1%, 카카오 원가 부담",
  "1분기 연결 매출은 9751억원(+2.5%)이었지만 영업이익은 164억원으로 전년 대비 56.1% 급감했어요. 회사는 카카오 등 주요 원재료 가격 부담으로 수익성이 나빠졌다고 설명했고, 국내 매출은 소비 둔화로 소폭 줄고 인도 중심으로 해외만 늘었어요. 원가 급등이 이익을 갉아먹으며 2024년 6월 이후 하락 국면이 이어진 핵심 원인이었어요.",
  "https://biz.sbs.co.kr/amp/article/20000233575", "SBS Biz")
# ---- 하림(136480)
N("136480", "2023-11-02", "+", "earn", "3Q23 영업익 152억원 +108%, 익산 신공장 안정화",
  "3분기 매출 3879억원(+5.6%), 영업이익 152억원(+108.2%)을 공시했어요. 리모델링한 익산 본사 공장이 안정화돼 생산성이 높아졌고, 국내 도계 물량이 약 3% 줄며 소닭 시세가 kg당 2695원에서 3090원으로 14.7% 올랐어요. 닭값 강세와 신공장 효율 개선이 겹치며 2022년 9월~2023년 12월 상승 국면을 뒷받침한 실적이었어요.",
  "https://dealsite.co.kr/articles/112346", "딜사이트")
# ---- 흥국에프엔비(189980)
N("189980", "2025-09-05", "-", "news", "순이익 3년 연속 감소(119억→52억원), 주가 1690원",
  "2024년 매출은 1026억원(+1.5%), 영업이익은 107억원(+3.9%)으로 정체된 반면 순이익은 2022년 119억원에서 2023년 87억원, 2024년 52억원으로 계속 줄었어요. 금융수익이 31억원에서 10억원으로 줄고 금융비용은 41억원에서 52억원으로 늘었으며, 공모가 2만원이던 주가는 9월 3일 1690원까지 내려왔어요. 성장 정체와 이익 감소가 2022년 4월 이후 장기 하락 국면의 배경이었어요.",
  "https://dealsite.co.kr/articles/147586", "딜사이트")
# ---- 한국맥널티(222980)
N("222980", "2024-12-04", "-", "cat", "3회차 CB 전액 풋옵션 행사, 주가 7천원대→3천원대",
  "3회차 전환사채의 최저 전환가(7300원)를 주가가 밑돌면서 만기를 1년 반가량 남기고 전액 조기상환청구(풋옵션)가 들어왔어요. CB 발행 당시 7000원대였던 주가는 올해 3000원대로 떨어졌고, 전환가도 1회차 1만2800원에서 4회차 4208원으로 3분의 1 수준이 됐어요. 8월 10억원 규모 자사주 신탁(약 5억5700만원 매입)에도 주가가 계속 밀린 것이 2022년 4월 이후 하락 국면을 보여줘요.",
  "https://dealsite.co.kr/articles/132294", "딜사이트")
# ---- 크라운제과(264900)
N("264900", "2025-08-14", "-", "earn", "2Q25 순이익 36억원 -36.1%, 원재료·판관비 부담",
  "크라운제과의 2분기 순이익은 36억원으로 전년 대비 36.1% 줄었어요. 원·부자재 가격 상승으로 매출원가가 늘고 판관비도 증가한 탓이에요(지주사 크라운해태홀딩스 연결 영업이익은 146억원, -21.5%). 내수 의존도가 높은 제과 사업의 원가 부담이 2022년 4월 이후 이어진 하락 국면의 배경이었어요.",
  "https://dealsite.co.kr/articles/146580", "딜사이트")
N("103840", "2026-01-13", "-", "news", "3Q25 누적 영업익 30억원에도 부채비율 232.7% 재무 부담",
  "2025년 3분기 누적 매출은 1334억원(+0.9%), 영업이익은 30억원(전년 동기 1억원)으로 개선됐고 순이익도 8억원으로 흑자 전환했어요. 하지만 연매출은 2023년 1913억원에서 2024년 1763억원으로 줄었고, 부채비율은 2025년 3분기 말 232.7%로 여전히 높았어요. 2024년 증권가가 기대했던 연 영업이익 100억원과는 거리가 먼 이익 규모와 약한 재무 체력이 2025년 8월 이후 하락 국면에서 반등을 막은 배경이에요.",
  "https://www.newstomato.com/ReadNews.aspx?no=1287361", "IB토마토")
# ---- 매일유업(267980)
N("267980", "2025-05-23", "-", "earn", "1Q25 영업익 130억원 -33.3%, 환율·원재료·인건비 부담",
  "1분기 연결 매출은 4588억원(+3.3%)이었지만 영업이익은 130억원으로 33.3% 줄었어요. 회사는 환율 상승, 국제 원재료 가격 상승, 제조·가공비 증가와 통상임금 적용에 따른 인건비 증가를 원인으로 들었어요. 저출산으로 흰 우유 수요가 줄어드는 가운데 원가 부담까지 겹친 것이 2019년 9월 이후 장기 하락 국면의 흐름을 보여줘요.",
  "https://news.tf.co.kr/read/economy/2208188.htm", "더팩트")
N("097950", "2024-11-12", "-", "earn", "3Q24 식품 영업익 1613억원 -31.1%, 내수 부진",
  "3분기 CJ대한통운 제외 매출은 4조6204억원(-1.1%), 영업이익은 2764억원으로 제자리였지만, 핵심인 식품 부문 영업이익이 1613억원으로 31.1% 급감했어요. 국내 식품 매출이 1조5690억원으로 6% 줄었고, 해외 식품(+5%)과 바이오(영업이익 +74.9%)가 이를 메우지 못했어요. 본업인 식품의 이익 체력이 꺾인 것이 2024년 7월 이후 하락 국면 초기의 핵심 원인이었어요.",
  "https://www.asiae.co.kr/en/article/2024111209054554598", "아시아경제")
N("136490", "2024-01-02", "-", "news", "하림푸드 인수·익산 투자 부담, 부채비율 206%",
  "선진이 하림지주로부터 하림푸드를 147억원에 인수하고 익산 1차 육가공 공장에 약 1500억원을 투입할 계획이 알려졌어요. 2023년 3분기 누적 영업이익은 781억원으로 좋았지만, 총차입금이 2017년 2606억원에서 7162억원(단기성 89.8%)으로 늘고 부채비율이 206.32%, 차입금의존도가 52.4%에 달했어요. 그룹 투자 부담과 재무 리스크가 이익 개선을 가리며 2022년 5월~2025년 3월 하락 국면을 이어간 배경이에요.",
  "https://newstomato.com/ReadNews.aspx?no=1213999", "IB토마토")
N("264900", "2026-11-13", "-", "earn", "3Q26 영업익 19억원, 30%대 감소·원가 부담",
  "크라운제과의 3분기 영업이익은 19억원으로 전년 대비 30%대 감소했고 매출도 줄었어요(같은 날 해태제과식품 영업이익은 55억원, -33.7%). 크라운해태 측은 나프타 등 주요 원료와 해외 수입 원재료 가격 상승으로 원가 부담이 누적됐다며, 원가 절감과 가격 조정 효과를 기대한다고 밝혔어요. 원가 부담이 해마다 이어진 것이 2022년 4월 이후 진행 중인 하락 국면의 배경이에요.",
  "https://www.koreancenter.or.kr/news/articleView.html?idxno=1439213", "연합뉴스")
N("101530", "2023-06-29", "-", "news", "정부 압박에 아이비 10% 가격 인하, '영업이익 크게 감소'",
  "정부의 식품 가격 인하 압박 속에 해태제과는 7월 1일부터 크래커 점유율 1위 제품 '아이비 오리지널' 가격을 10% 내리기로 했어요. 회사는 원가 부담이 가속화되며 영업이익이 크게 줄고 있어 다른 제품까지 인하를 넓히기는 어렵다고 밝혔어요. 원가 상승을 가격에 넘기기 어려운 환경이 2021년 5월~2023년 10월 하락 국면의 막바지까지 수익성을 짓눌렀어요.",
  "https://www.newsis.com/view/NISX20230629_0002356726", "뉴시스")

