# ---- CJ대한통운(000120)
N("000120", "2023-11-30", "+", "cat", "알리 물량 반년 새 2.6배, 17일 +10.35%·30일 +5.88%",
  "중국 쇼핑앱 알리익스프레스와 테무의 국내 이용자가 급증하면서 CJ대한통운의 3분기 알리 국내 물동량이 반년 만에 2.6배로 늘었다는 분석이 나왔어요. 주가는 11월 17일 10.35% 급등한 뒤 10거래일간 상승을 이어갔고, 30일에도 5.88% 올라 11만3500원을 기록했어요. 한국투자증권은 목표주가 12만5000원을 제시했어요. C커머스 물량이라는 회사 고유 성장 동력이 2023년 하반기 반등 국면을 이끌었어요.",
  "https://www.smarttoday.co.kr/ko-kr/articles/38895", "스마트투데이")
N("000120", "2026-06-11", "-", "earn", "1분기 영업익 921억, 컨센서스 1165억 21% 하회·3개월 -29%",
  "CJ대한통운은 2026년 1분기 매출 3조2145억원(+7.4%), 영업이익 921억원(+7.9%)을 냈지만 시장 컨센서스 1165억원을 크게 밑돌았어요. 쿠팡 대응 투자와 주 7일 배송 '매일오네' 허브 운영비, 유가 급등이 부담으로 꼽혔고 하나증권(16만5000원→12만원), iM증권(19만원→14만원) 등이 목표가를 낮췄어요. 주가는 3월 10일 11만3800원에서 6월 11일 7만9100원으로 29.43% 빠졌는데 같은 기간 코스피는 39.73% 올랐어요. 기대를 밑돈 실적과 비용 부담이 2026년 하락 국면을 주도했어요.",
  "https://news.tf.co.kr/read/economy/2331688.htm", "더팩트")
N("000120", "2026-02-10", "+", "earn", "4분기 영업익 1596억 분기 최대(+3.4%), 매출 3조1771억",
  "CJ대한통운은 2025년 4분기 연결 매출 3조1771억원(+0.5%), 영업이익 1596억원(+3.4%)으로 매출과 영업이익 모두 분기 최대치를 냈다고 공시했어요. 글로벌 부문 영업이익이 383억원으로 37.3% 늘고 계약물류 매출이 10.5% 증가했지만, 택배 부문 영업이익은 618억원으로 11.2% 줄었고 연간 영업이익(5081억원)도 소폭 감소했어요. 사상 최대 분기 실적이 2025년 상승 국면의 정점 무렵에 확인된 셈이지만 핵심인 택배 이익 감소는 이후 하락의 예고이기도 했어요.",
  "https://www.hankyung.com/amp/202602105419P", "한국경제")
N("000120", "2024-11-21", "-", "earn", "3분기 매출 2조9800억, 추정치 3.1%·EPS 12% 하회",
  "CJ대한통운의 2024년 3분기 매출은 2조9800억원으로 1.3% 늘었고 순이익은 548억원(+5.2%), 주당순이익은 2672원이었어요. 하지만 매출은 애널리스트 추정치를 3.1%, 주당순이익은 12% 밑돌았어요. 성장 둔화 속에 기대에 못 미친 실적이 이어진 것이 2024년 하락 국면의 배경이었어요.",
  "https://simplywall.st/stocks/kr/transportation/kose-a000120/cj-logistics-shares/news/cj-logistics-third-quarter-2024-earnings-misses-expectations", "Simply Wall St")
# ---- 천일고속(000650)
N("000650", "2025-12-04", "+", "cat", "고속터미널 재개발 기대에 9연속 상한가, 장중 51만8000원",
  "서울시가 서울고속버스터미널 부지를 60층 내외 주상복합으로 재개발하는 사전협상에 착수하자, 터미널 지분 16.67%(3분기 평가액 3064억원)를 가진 천일고속이 9거래일 연속 상한가를 기록했어요. 12월 4일 장중 51만8000원까지 올랐다가 고점 대비 27.31% 떨어진 37만6500원에 마감했어요. 유통주식이 약 14%에 불과한 반면 회사는 1~3분기 영업손실 약 51억원의 적자 상태였어요. 실적이 아닌 재개발 테마와 얇은 유통물량이 +881% 국면을 만들었어요.",
  "https://www.heraldk.com/article/2025120418115151461", "헤럴드경제")
N("000650", "2026-02-25", "-", "earn", "2025년 영업손실 59억 적자 지속, 주가 고점 대비 약 47% 하락",
  "천일고속은 2025년 매출 456억원(+1.8%), 영업손실 59억원, 순손실 56억원의 잠정 실적을 공시했어요. 주가는 2월 25일 27만6000원으로 2025년 12월 4일 장중 고점 51만8000원에서 약 47% 내려왔어요. 기사는 터미널 복합개발 논의가 아직 걸음마 단계라 구체적 진척까지 상당한 시간이 필요하다고 짚었어요. 적자 실적과 더딘 재개발 일정이 테마 급등분을 되돌리는 하락 국면의 배경이었어요.",
  "https://v.daum.net/v/20260225162849853", "시사위크")
# ---- 국보(001140)
N("001140", "2025-05-21", "-", "cat", "2년 연속 감사의견 거절로 상장폐지 결정, 부채비율 668%",
  "국보는 2023·2024사업연도 감사보고서에서 연속으로 감사의견 거절을 받았고, 4월 14일 개선기간 종료 뒤 낸 개선계획 심의요청도 받아들여지지 않아 한국거래소가 5월 20일 상장폐지를 결정했어요. 2024년 영업손실 78억원, 순손실 272억원에 부채비율 668.45%, 순차입금비율 424.84%로 재무도 크게 나빠졌어요. 2022년 유상증자로 지분 20.74%를 확보한 무궁화신탁의 경영개선도 차질이 예상됐어요. 감사의견 거절과 상장폐지가 주가 -100% 국면을 결정지었어요.",
  "https://newstomato.com/ReadNews.aspx?no=1262606", "IB토마토")
# ---- 선광(003100)
N("003100", "2023-04-25", "-", "cat", "SG증권발 매도 폭탄에 이틀 연속 하한가",
  "4월 24일 SG증권 창구에서 대량 하한가 매도 주문이 쏟아진 뒤 선광은 삼천리·서울가스·대성홀딩스·다우데이타·세방과 함께 25일에도 시초가부터 하한가로 떨어지며 이틀 연속 하한가를 기록했어요. 기사는 시장에서 소화하기 힘든 반대매매 물량이 나오고 있다고 전했고, 6개사는 이틀 만에 시가총액의 절반을 잃었어요. 이 종목들은 최대주주 지분율과 신용잔고 비율이 높고 거래량이 적은 채 1년간 꾸준히 오른 공통점이 있었어요. 주가조작 의혹 계좌의 붕괴가 -91% 하락 국면의 출발점이었어요.",
  "https://www.smarttoday.co.kr/ko-kr/articles/29393", "스마트투데이")
# ---- 세방(004360)
N("004360", "2023-04-25", "-", "cat", "SG증권발 매도 폭탄에 이틀 연속 하한가",
  "4월 24일 SG증권 창구에서 대량 하한가 매도 주문이 쏟아진 뒤 세방은 선광·삼천리·서울가스·대성홀딩스·다우데이타와 함께 25일에도 시초가부터 하한가로 떨어지며 이틀 연속 하한가를 기록했어요. 기사는 시장에서 소화하기 힘든 반대매매 물량이 쏟아지고 있다고 전했고, 6개사는 이틀 만에 시가총액의 절반을 날렸어요. 높은 대주주 지분율·신용잔고, 적은 거래량 속에 1년간 꾸준히 오른 종목들이었어요. 주가조작 의혹 계좌의 붕괴가 2023년 -77% 하락 국면을 만든 핵심 사건이었어요.",
  "https://www.smarttoday.co.kr/ko-kr/articles/29393", "스마트투데이")
# ---- 흥아해운(003280)
N("003280", "2024-01-17", "+", "macro", "홍해 리스크에 장중 +19.86%, 1월에만 약 100% 상승",
  "미국이 예멘 후티 반군 근거지를 공습하며 홍해 항행이 나빠지고 물류비가 오를 것이라는 기대에 흥아해운은 1월 17일 오전 5060원(+19.86%)까지 올라 52주 최고가를 기록했어요. 2023년 말 종가 2485원 대비 이달 들어서만 약 100% 오른 수준이었어요. 기사는 2023년 예상 매출 2140억원, 영업이익 357억원을 소개했어요. 회사 고유 재료보다 홍해 사태라는 지정학 테마가 +155% 상승 국면의 정점을 만들었어요.",
  "https://core.asiae.co.kr/article/2024011710520565769", "아시아경제")
N("003280", "2026-03-03", "+", "macro", "호르무즈 해협 봉쇄에 시초가 상한가(+29.73%, 2330원)",
  "미국·이스라엘의 이란 공습 뒤 이란 혁명수비대가 호르무즈 해협을 봉쇄하자 3월 3일 흥아해운은 장 시작과 함께 534원(29.73%) 오른 2330원으로 상한가에 진입했어요. NH투자증권은 VLCC 평균 수익이 하루 20만9000달러로 한 주 만에 39% 뛰었다고 짚었어요. STX그린로지스·대한해운·HMM 등도 함께 오른 업종 전체 랠리였어요. 중동 전쟁발 운임 급등 기대가 2025~2026년 상승 국면의 마지막 급등을 이끌었어요.",
  "https://www.mt.co.kr/article/2026030309412612887", "머니투데이")
# ---- 대한항공(003490)
N("003490", "2026-07-15", "+", "earn", "2분기 영업익 2618억, 컨센서스 843억의 3배·목표가 3만8000원",
  "신한투자증권은 대한항공 2분기 별도 매출이 5조199억원(+25.9%)으로 컨센서스 4조9560억원을 넘었고, 영업이익 2618억원(-34.4%)은 연료비가 111% 급증했는데도 컨센서스 843억원을 크게 웃돌았다고 분석했어요. 화물 운임이 41.8% 오르며 화물 매출이 46.1% 늘어난 덕분이었어요. 목표주가는 3만5000원에서 3만8000원으로 9% 올렸어요. 유가 부담 속에서도 화물 초강세로 기대를 넘은 실적이 장기 상승 국면을 떠받쳤어요.",
  "https://view.asiae.co.kr/article/2026071514521691704", "아시아경제")
# ---- 티웨이홀딩스(004870)
N("004870", "2025-01-21", "+", "cat", "대명소노 경영권 분쟁 본격화에 장중 +24.14%(972원)",
  "티웨이항공 2대 주주 대명소노그룹(지분 26.77%)이 현 경영진 사퇴와 유상증자를 요구하는 서한을 보낸 사실이 알려지며, 1월 21일 오전 티웨이홀딩스는 972원으로 24.14% 올랐어요. 최대주주인 티웨이홀딩스와 예림당 합산 지분은 30.07%로 격차가 2.3%포인트에 불과해 지분 경쟁 기대가 커졌어요. 경영권 분쟁 프리미엄이 +128% 상승 국면의 정점을 만든 재료였어요.",
  "https://view.asiae.co.kr/article/2025012109503171002", "아시아경제")
N("004870", "2025-02-18", "-", "cat", "예림당·대명소노 지분 협상 소식에 -23.83%(716원)",
  "대명소노그룹이 최대주주 예림당과 지분 인수 협상에 나섰다는 소식에 경영권 분쟁이 봉합될 것이라는 전망이 나오며, 2월 18일 티웨이홀딩스는 23.83% 떨어진 716원에 마감했어요. 대명소노는 정기주총 의안 상정 요구와 주주명부 열람 가처분 신청도 취하했어요. 지분 경쟁 기대가 사라지면서 분쟁 프리미엄이 빠지기 시작한 것이 -76% 하락 국면의 출발점이었어요.",
  "https://www.fnnews.com/news/202502181545137465", "파이낸셜뉴스(연합뉴스)")
# ---- 동방(004140)
N("004140", "2021-02-15", "+", "cat", "천안 첨단 물류센터 건립 소식에 상한가, 1월 18일 대비 +124.55%",
  "동방은 2월 15일 전일 대비 29.99% 오른 9970원으로 상한가를 기록했고, 1월 18일 이후 상승률은 124.55%에 달했어요. 기사는 2월 10일 천안 첨단 물류센터 건립 소식 이후 강세가 이어졌다고 전했으며, 최근 5일간 개인은 127만주를 순매도하고 외국인이 103만주를 순매수했어요. 물류 테마 급등이 만든 이 고점이 이후 -82% 장기 하락 국면의 출발점이 됐어요.",
  "https://www.asiae.co.kr/en/article/2021021514350847139", "아시아경제")
N("004140", "2024-06-17", "+", "earn", "1분기 순이익 104억, 4배 가까이 증가·댐피어 376억 계약 반영",
  "동방은 2024년 1분기 연결 매출 2105억원(+7.3%), 영업이익 93억원(+3%)을 냈고, 과거 충당금 환입 덕에 순이익이 27억원에서 104억원으로 4배 가까이 늘었어요. 2월부터 공급을 시작한 376억원 규모 호주 댐피어 중량물 해상운송 계약이 연간 실적에 반영될 예정이고, 자회사가 운영하는 영일만항 확장 수혜도 기대됐어요. 영업외 이익이 컸던 만큼 본업 성장은 제한적이었고, 이 무렵이 +94% 반등 국면의 끝자락이었어요.",
  "https://www.etoday.co.kr/news/view/2370484", "이투데이")
N("004140", "2024-11-20", "-", "earn", "3분기 순이익 12.9억(-69%), 매출 +16%에도 비용 급증",
  "동방의 2024년 3분기 매출은 2158억원으로 16% 늘었지만 순이익은 12억9000만원으로 69% 줄었고, 주당순이익은 87원에서 27원으로 떨어졌어요. 순이익률은 2.2%에서 0.6%로 낮아졌는데 비용 증가가 원인으로 지목됐어요. 1분기 충당금 환입 효과가 사라진 뒤 수익성 약화가 드러난 것이 2024년 하반기 이후 하락 국면의 배경이었어요.",
  "https://simplywall.st/stocks/kr/transportation/kose-a004140/dongbang-transport-logistics-shares/news/dongbang-transport-logistics-third-quarter-2024-earnings-eps", "Simply Wall St")
# ---- 흥아해운(003280) 하락
N("003280", "2026-04-08", "-", "macro", "미국·이란 2주 휴전 합의에 장초반 -18.97%(3075원)",
  "미국과 이란이 2주간 휴전에 합의했다는 소식에 4월 8일 오전 흥아해운은 전일 대비 720원(18.97%) 급락한 3075원에 거래됐어요. 기사는 흥아해운이 전쟁 국면에서 유조선대를 미리 확충해 둔 점이 주목받아 변동폭이 커졌다고 설명했어요. 호르무즈 봉쇄 수혜 기대가 꺼진 것이 -61% 하락 국면의 핵심 계기였어요.",
  "https://www.hankyung.com/article/2026040861776", "한국경제")
# ---- 한진(002320)
N("002320", "2023-05-15", "-", "earn", "1분기 영업익 235억(-31.7%), 순손실 적자 전환",
  "한진은 2023년 1분기 연결 매출 6751억원(-4.4%), 영업이익 235억원(-31.7%)을 냈고 순이익은 4억7000만원 손실로 적자 전환했어요. 경기 침체에 따른 물동량 감소와 대전 스마트 메가허브 등 택배 자동화 투자비 증가, 부산항 컨테이너 터미널 물동량 감소가 원인으로 꼽혔고, 2022년 6월 쿠팡의 자체 배송 전환으로 택배 물량이 약 15% 줄었던 영향도 있었어요. 연간 목표(매출 3조700억원·영업이익 1400억원) 달성도 불확실하다는 평가가 나오며 장기 하락 국면 후반의 실적 부담을 보여줬어요.",
  "https://biz.newdaily.co.kr/site/data/html/2023/05/15/2023051500159.amp.html", "뉴데일리")
# ---- 동양고속(084670)
N("084670", "2025-12-29", "+", "cat", "서울고속터미널 복합개발 테마로 연간 +912% 코스피 1위",
  "동양고속은 2025년 1월 1일~12월 26일 912.24% 올라 유가증권시장 상승률 1위를 기록했어요. 서울시가 서울고속터미널 부지 복합개발을 추진하면서 급등이 시작됐고, 회사가 서울고속터미널 지분 0.17%를 보유했다는 이유로 투기성 자금이 몰렸다고 기사는 설명했어요. 지분 16.67%를 가진 천일고속(+901%)과 함께 움직인 전형적인 테마성 급등이 이 국면의 정체였어요.",
  "https://www.hankyung.com/article/202512290596i", "한국경제")
# ---- HMM(011200)
N("011200", "2024-01-24", "+", "news", "홍해 사태로 SCFI +150%, 대신증권 올해 영업익 전망 1500억→2.8조·목표가 2.1만원",
  "후티 반군의 홍해 상선 위협으로 컨테이너선이 희망봉으로 우회하면서 SCFI는 1월 19일 2239.61로 2023년 10월 말 900선 대비 약 150% 올랐고, KCCI는 8주 연속 상승했어요. 대신증권은 HMM의 2024년 영업이익 전망을 1500억원에서 2조8000억원으로 높이고 목표주가를 2만1000원(+23.5%)으로 올렸어요. 2023년 10월 저점 이후 상승 국면의 출발점이 된 운임 급반등이었어요.",
  "https://biz.newdaily.co.kr/site/data/html/2024/01/24/2024012400140.amp.html", "뉴데일리경제")
# ---- 팬오션(028670)
N("028670", "2026-07-13", "+", "news", "올해 영업익 전망 6000억 돌파 상향, VLCC 인도·BDI 2800 반등",
  "하나증권은 7월 8일 팬오션의 2026년 영업이익 전망을 5790억원에서 6018억원으로 올렸고, LS증권(6060억원)·대신증권(6080억원)도 6000억원대를 제시했어요. 2분기 전망치는 매출 1조6080억원(+24%), 영업이익 1607억원(+31%)이었고, 중동 리스크에 따른 유조선 운임 상승과 SK해운에서 사들인 VLCC 인도(5월 말 시작), 7월 4일 715에서 2800 안팎으로 반등한 BDI가 근거였어요. 장기운송계약(COA)이 영업이익의 68~70%를 차지해 하방이 단단하다는 평가가 상승 국면을 뒷받침했어요.",
  "https://www.fnnews.com/news/202607100757253683", "파이낸셜뉴스")
N("011200", "2022-12-20", "-", "news", "SCFI 5109→1123 폭락, 내년 영업익 전망 3개월 새 6.29조→2.81조(-55%)",
  "컨테이너 운임지수 SCFI는 고점 5109에서 12월 16일 1123.29까지 떨어졌어요. 이에 따라 HMM의 4분기 영업이익 전망은 3개월 전 2조834억원에서 1조3773억원으로, 2023년 영업이익 전망은 6조2856억원에서 2조8074억원으로 55% 넘게 깎였어요. 팬데믹 운임 거품이 꺼지며 이익 전망이 연속 하향된 것이 2022~2023년 하락 국면의 핵심이었어요.",
  "https://www.asiae.co.kr/en/article/2022122009453560187", "아시아경제")
# ---- 팬오션(028670) 하락
N("028670", "2023-12-20", "-", "cat", "HMM 우선협상대상자 선정 후 유상증자 우려에 12/19 -10.1%, 목표가 7000→4500원",
  "12월 18일 팬오션-JKL 컨소시엄이 약 6조4000억원에 HMM 우선협상대상자로 선정되자, 인수자금용 최대 3조원 유상증자 우려가 퍼지며 팬오션 주가는 19일 10.10%, 20일 2.32% 떨어져 4000원에 마감했어요. 반면 하림은 이틀 연속 상한가였고, 대신증권은 팬오션 목표주가를 7000원에서 4500원으로 낮췄어요. 시가총액 2조원 수준 회사가 감당하기 벅찬 인수 부담이 하락 국면의 마지막 국면을 만든 사건이었어요.",
  "https://v.daum.net/v/20231220165120434", "경향신문")
# ---- 아시아나항공(020560)
N("020560", "2026-02-04", "-", "earn", "2025년 영업손실 3452억 적자전환, 주가 7500원대로 합병비율 불리 우려",
  "아시아나항공은 2025년 매출 7조2668억원(2024년 8조3186억원), 영업손실 3452억원(2024년 영업이익 2757억원)으로 적자전환했어요. 화물사업 매각으로 매출이 줄고 3분기 영업손실이 1492억원에 달했으며 부채비율은 1187%였어요. 한때 2만원을 넘던 주가는 2월 3일 7500원대로 내려왔고, 2026년 12월 대한항공 합병을 앞두고 낮은 주가가 합병비율에서 아시아나 주주에게 불리하다는 전망이 하락 국면을 굳혔어요.",
  "https://news.bizwatch.co.kr/article/industry/2026/02/03/0028", "비즈니스워치")
# ---- 대한해운(005880)
N("005880", "2024-01-26", "+", "cat", "홍해 사태 해운 테마로 1/17 장중 3100원 1년 최고, 일평균 거래량 4652만주 1위",
  "후티 반군의 선박 공격과 미·영 공습, 이란의 유조선 나포로 중동 긴장이 높아지고 해상운임이 급등하자 대한해운은 1월 17일 장중 3100원까지 올라 최근 1년 최고가를 찍었어요. 1월 2~25일 일평균 거래량은 4651만주로 전체 시장 1위였지만, 기사 작성 시점에는 2100원 안팎으로 상승분 대부분을 반납했어요. 2023년 10월 저점 이후 상승 국면에 해운 테마 수급이 불을 붙인 장면이었어요.",
  "https://www.fnnews.com/news/202401261018045442", "파이낸셜뉴스")
N("005880", "2024-11-15", "-", "earn", "3분기 영업익 678억(-9.1%), 정기 입거수리·용선료 증가",
  "대한해운의 2024년 3분기 매출은 4188억원으로 24.5% 늘었지만 영업이익은 678억원으로 9.1% 줄었어요. 쉘에 대선한 LNG선 3척 등 신조선 효과로 외형은 커졌으나 선박 정기 입거수리와 용선료 증가가 이익을 깎았어요. 매출 성장에도 이익이 뒷걸음질한 점이 2024년 6월 이후 하락 국면에서 반등 동력을 약하게 만든 배경이었어요.",
  "https://dealsite.co.kr/articles/131618", "딜사이트")
# ---- KSS해운(044450)
N("044450", "2026-01-30", "+", "cat", "8264억 장기대선계약(매출의 160%) 공시에 +8.7%",
  "KSS해운은 BGN그룹 6척, 태국 PTT 1척 등 총 8264억원 규모의 장기대선계약을 공시했는데, 2024년 연결 매출 5179억원의 약 160%에 달하는 규모였어요. BGN 계약은 2028년부터 5년씩 4개 트랜치(각 약 1540억원), PTT 계약은 2026년 3월~2028년 3월 약 478억원이었고, 주가는 장중 9870원으로 8.7% 올랐어요. 장기 매출 가시성을 높인 대형 계약으로 2023년 10월 이후 상승 국면을 이어 준 촉매였어요.",
  "https://core.asiae.co.kr/article/2026013013290418477", "아시아경제")
# ---- 한익스프레스(014130)
N("014130", "2025-10-29", "-", "news", "주가 3310원·PBR 0.39배, 코로나 특수 소멸·석화 고객 부진에 저점",
  "한익스프레스 주가는 10월 28일 3310원, 시가총액 약 397억원으로 코로나19 시기 8000원 이상이던 고점에서 크게 내려왔고 PBR은 0.39배였어요. 코로나 물동량 특수가 끝난 뒤 수익성이 떨어졌고 핵심 고객인 한화솔루션 케미칼·한화토탈 등 석유화학 업황 침체가 겹쳤으며, 회사는 주가 부양책에 대해 '결정된 내용은 없다'고만 밝혔어요. 증권사 커버리지 부재와 낮은 회전율까지 더해져 2023년 말 이후 장기 하락 국면이 이어진 배경이에요.",
  "https://dealsite.co.kr/articles/149894", "딜사이트")
# ---- KCTC(009070)
N("009070", "2024-07-26", "+", "cat", "티몬·위메프 셧다운에 쿠팡 관련주로 +4.39%(4280원)",
  "큐텐 계열 티몬·위메프의 정산 지연으로 판매자가 이탈하며 쿠팡 독점 가능성이 부각되자, 쿠팡과 물류·창고 협력 관계로 쿠팡 관련주로 묶인 KCTC는 7월 26일 오전 4.39% 오른 4280원에 거래됐어요. 기사에 실적이나 공시 언급은 없고 순수 테마성 수급이었어요. 2023년 9월 이후 상승 국면의 막바지(고점권)를 테마가 밀어 올린 장면이에요.",
  "https://view.asiae.co.kr/article/2024072610293428585", "아시아경제")
N("009070", "2025-12-11", "+", "cat", "PER 4.6배 저평가 재평가에 장중 +18.5%(6400원), 거래량 100배 폭증",
  "KCTC는 12월 11일 장중 전일 대비 18.52% 오른 6400원(고가 6890원)에 거래됐고, 거래량은 전날 약 16만주에서 약 1418만주로 늘었어요. PER 4.57배·PBR 0.4배의 저평가에 부산항 신항 양곡부두 민간투자사업 등 인프라 이슈가 겹쳤고, 외국인 보유율은 11월 초 3.2%에서 12월 10일 4.4%로 올랐어요. 2025년 3월 이후 두 배 넘게 오른 상승 국면 후반의 가속 구간이었어요.",
  "https://www.topstarnews.net/news/articleView.html?idxno=15902958", "톱스타뉴스")
# ---- 한국공항(005430)
N("005430", "2024-07-29", "+", "news", "1분기 매출 1499억(+33.8%)·영업익 150억 흑자전환, 아시아나에어포트 통합 시 점유율 71.5%",
  "한국IR협의회는 한국공항의 2024년 1분기 매출이 1499억원으로 33.8% 늘고 영업이익 150억원(영업이익률 10.0%, +14.7%p)으로 흑자전환했다고 짚었어요. 엔데믹으로 2023년 운항편수가 24.5% 늘며 전 사업부 매출이 회복됐고, 아시아나에어포트와 합치면 2023년 매출 기준 점유율 71.5%의 최대 지상조업사가 돼 규모의 경제가 기대된다고 봤어요. 여객 회복에 따른 실적 반등과 통합 수혜 기대가 2022년 9월~2024년 7월 상승 국면의 근거였어요.",
  "https://www.etoday.co.kr/news/view/2384963", "이투데이")
N("005430", "2025-09-03", "+", "news", "하나증권, 아시아나 합병 시너지 기대…상반기 매출 3172억(+6%)·영업익 260억(-11%)",
  "하나증권은 한국공항이 아시아나에어포트와 같은 지상조업을 하는 만큼 대한항공·아시아나 합병 후 인력·설비 효율화로 비용 효율이 좋아질 것으로 봤어요. 아시아나에어포트는 지난해 매출 2461억원, 순이익 202억원을 냈고, 한국공항의 약 1000억원 현금성 자산 활용도 제안됐어요. 상반기 영업이익은 260억원으로 11% 줄었지만, 통합 시너지 기대가 2025년 4월 이후 상승 국면을 지탱한 논리였어요.",
  "https://www.asiae.co.kr/en/article/2025090307294429141", "아시아경제")
N("084670", "2025-12-31", "-", "cat", "12/19 장중 17만2800원 정점 후 12/30 7만3200원, 상한가 12차례 테마 과열 반락",
  "동양고속은 11월 중순까지 7000원대였다가 서울고속터미널 초고층 복합개발 소식에 11월 19일 첫 상한가 이후 12월 17일까지 12차례 상한가를 기록하고 12월 19일 장중 17만2800원까지 올랐어요. 그러나 12월 30일 종가는 7만3200원으로 고점 대비 절반 넘게 밀렸어요. 지분 0.17%에 기댄 투기성 급등이 꺼지기 시작한 시점으로, 이후 하락 국면의 출발점이에요.",
  "https://mobile.newsis.com/view/NISX20251231_0003460870", "뉴시스")
N("011200", "2022-09-05", "-", "news", "SCFI 사상 최대 주간 낙폭에 52주 신저가 2만800원, 신영 목표가 4.2만→2.45만원",
  "9월 2일 SCFI가 2847.62로 한 주 새 306.64포인트 떨어지며 2009년 집계 이후 최대 낙폭을 기록하자 HMM은 9월 5일 장중 2만800원까지 밀려 52주 신저가를 썼어요. 신영증권은 목표주가를 4만2000원에서 2만4500원으로, 메리츠증권은 2만9000원에서 2만7000원으로, 대신증권은 3만원에서 2만9000원으로 낮췄어요. 운임 하락과 목표가 연쇄 하향이 2022년 5월 이후 하락 국면을 가속했어요.",
  "https://economist.co.kr/article/view/ecn202209050010", "이코노미스트")
N("005880", "2023-02-14", "-", "earn", "2022년 영업익 2677억(+31%)에도 순이익 1723억(-43.8%)",
  "대한해운의 2022년 연결 매출은 1조6120억원(+39.7%), 영업이익은 2677억원(+31.3%)으로 늘었지만 순이익은 1723억원으로 43.8% 줄었어요. 2021년에 있던 소송 승소에 따른 충당금 환입과 선박 매각 이익이 사라진 기저효과 때문이었어요. 호황에도 순이익이 반토막 난 점이 2022년 5월 이후 하락 국면에서 투자 심리를 돌리지 못한 배경이에요.",
  "https://dealsite.co.kr/articles/99141", "딜사이트")
N("028670", "2026-05-07", "+", "earn", "1분기 영업익 1409억(+24.4%), 컨센서스 7% 상회·NH 목표가 6700→7200원",
  "팬오션의 2026년 1분기 매출은 1조5089억원(+8.3%), 영업이익은 1409억원(+24.4%)으로 컨센서스를 7% 웃돌았어요. 탱커(+41.5%)와 LNG(+49.8%) 부문이 3월 이란 전쟁발 연료비 급등 부담을 상쇄했고, NH투자증권은 목표주가를 6700원에서 7200원으로 올리며 2026·2027년 영업이익 전망을 5%·2% 높였어요. 벌크 외 에너지 운송 확대(VLCC·MR탱커 확보)가 이익으로 확인되며 2024년 12월 이후 상승 국면을 뒷받침했어요.",
  "https://core.asiae.co.kr/article/2026050616194252861", "아시아경제")
N("005880", "2024-08-19", "-", "earn", "2분기 영업익 722억, 컨센서스 16.5% 하회·KB 목표가 2800→2600원",
  "대한해운의 2024년 2분기 영업이익은 722억원으로 10.6% 늘었지만 컨센서스를 16.5% 밑돌았어요. 기대했던 부동산 개발 사업 일회성 이익이 반영되지 않은 영향이 컸고, KB증권은 연결 벌크 자회사 부진과 LNG 마진 가정 조정을 반영해 2025년 이후 이익 전망을 낮추며 목표주가를 2800원에서 2600원으로 내렸어요(투자의견은 낙폭 과대로 매수 상향). 2024년 6월 고점 이후 하락 국면 초입의 기대 하회 실적이었어요.",
  "https://core.asiae.co.kr/article/2024081907531424742", "아시아경제")
N("020560", "2023-11-03", "-", "cat", "EU 조건 따른 화물사업(5000억~7000억) 매각 이사회 승인 후 급락, 연초 1.5만→1만원대",
  "EU가 대한항공과의 합병 승인 조건으로 아시아나의 화물사업 매각과 일부 중복 노선 반납을 요구했고, 아시아나 이사회가 화물사업 매각을 승인했어요. 화물사업 가치는 약 5000억~7000억원으로 거론됐는데, 주가는 EU 승인 기대에 급등했다가 매각 결정 이후 급락해 연초 1만5000원대에서 1만원대로 내려왔어요. 알짜 화물사업을 떼어내는 합병 조건이 2023년 이후 장기 하락 국면의 구조적 출발점이었어요.",
  "https://www.ytn.co.kr/_ln/0102_202311031715582120", "YTN")
# ---- 현대글로비스(086280)
N("086280", "2025-01-02", "+", "cat", "현대차·기아 6.7조 장기운송 계약 갱신, 주가 +13%",
  "현대차(3조3655억원)·기아(3조3340억원)와 2029년까지 장기 운송계약을 갱신했다고 발표하자, 1월 2일 주가가 장중 13.04% 오른 13만3500원으로 52주 신고가를 찍었어요. 이전 계약(2022~2024년, 1조9600억원)보다 물량 비중은 60%에서 50%로 줄었는데도 금액이 크게 늘어, NH투자증권은 운임이 30% 넘게 인상된 것으로 봤어요. 계열사 운임 인상으로 이익 체력이 한 단계 올라간다는 점을 확인시켜 장기 상승 국면의 핵심 재료가 됐어요.",
  "https://www.smarttoday.co.kr/ko-kr/articles/68894", "스마트투데이")
# ---- 티웨이항공(091810)
N("091810", "2025-12-29", "-", "cat", "4개월간 4000억 유상증자·3분기 영업손실 955억, 고점 대비 -65%",
  "티웨이항공 주가는 2025년 1월 24일 4110원으로 고점을 찍은 뒤 12월 26일 1434원까지 65% 넘게 빠졌어요. 2월 대명소노그룹이 티웨이홀딩스를 2500억원에 인수하며 경영권 분쟁 재료가 사라졌고, 12월 11일 1910억원 유상증자 결의까지 4개월간 4000억원을 증자로 조달했어요. 영업손실은 1분기 355억원, 2분기 790억원, 3분기 955억원으로 불어났고 부채비율은 4457%까지 올라, 분쟁 프리미엄 소멸과 적자·희석이 겹친 하락 국면이었어요.",
  "https://news.tf.co.kr/read/economy/2276591.htm", "더팩트")
# ---- 한진칼(180640)
N("180640", "2025-05-14", "+", "cat", "호반 지분 18.46%로 확대, 이틀 연속 상한가",
  "호반그룹 계열사가 한진칼 지분을 17.44%에서 18.46%로 늘리면서 조원태 회장 측(20.13%)과 격차가 1.67%포인트로 역대 최소로 좁혀졌어요. 주가는 5월 13일 상한가(+29.93%, 11만5900원)에 이어 14일에도 장중 상한가인 15만600원까지 오르며 상장 이후 최고가를 썼어요. 호반은 '단순 투자'라고 했지만 시장은 경영권 분쟁 가능성을 주가에 반영했고, 이것이 한진칼 대세 상승 국면의 대표 촉매였어요.",
  "https://news.tf.co.kr/read/economy/2205554.htm", "더팩트")
# ---- 제주항공(089590)
N("089590", "2024-12-30", "-", "news", "무안공항 참사, 주가 장중 -15.7% 상장 후 최저",
  "12월 29일 무안국제공항에서 제주항공 여객기가 사고를 내 179명이 숨지자, 30일 주가가 장중 최대 15.7% 떨어진 6920원으로 2015년 상장 이후 최저가를 기록했어요. 모회사 AK홀딩스도 장중 최대 12% 빠지며 16년 만의 최저가를 찍었어요. 제주항공 창사 첫 사망 사고로 안전 신뢰와 수요 위축 우려가 겹치며 장기 하락 국면을 깊게 만든 사건이었어요.",
  "https://thestar.com.my/business/business-news/2024/12/30/jeju-air-shares-slump-to-record-low-after-deadly-plane-crash", "The Star(로이터)")
N("089590", "2026-11-10", "+", "earn", "3분기 영업이익 549억 흑자전환, 매출 4896억",
  "제주항공은 3분기 별도 매출 4896억원, 영업이익 549억원을 내며 전년 동기 599억원 적자에서 흑자로 돌아섰어요. 엔저에 따른 일본 노선 수요 호조와 3분기 항공유 가격·원달러 환율 안정이 비용을 낮췄고, 정비 관련 일회성 부채 환입도 기여했어요. 2분기 524억원 적자 이후 수익성이 회복됐음을 숫자로 확인시켜 7월 이후 반등 국면을 뒷받침했어요.",
  "https://news.mtn.co.kr/article/2026110916422268897", "머니투데이방송")
# ---- 티웨이항공(091810)
N("091810", "2024-10-10", "+", "cat", "대명소노 지분 26.77%로 경영권 분쟁 부각, 주가 +12.5%",
  "2대주주 대명소노그룹이 JKL파트너스 지분을 웃돈을 주고 사들이고 콜옵션을 조기 행사하는 등 티웨이항공 경영권 확보에 나섰다는 소식에, 10월 10일 주가가 장중 12.5% 오른 3600원을 기록했어요. 대명소노 지분은 26.77%로 최대주주 예림당(29.97%)과 격차가 약 3%포인트로 좁혀졌어요. 경영권 분쟁 기대가 2025년 1월 고점까지 이어진 상승 국면의 핵심 재료였어요.",
  "https://view.asiae.co.kr/article/2024101009360391965", "아시아경제")
# ---- 진에어(272450)
N("272450", "2026-11-10", "+", "earn", "3분기 영업이익 78억 흑자전환, 역대 최대 매출 4131억",
  "진에어는 3분기 매출 4131억원(전년 대비 +36%, 분기 최대), 영업이익 78억원을 내며 전년 동기 225억원 적자에서 흑자로 돌아섰어요. 일부 증권사가 영업손실을 예상했던 만큼 기대를 웃돈 실적이었어요. 2027년 3월 17일 에어부산·에어서울을 흡수한 통합 진에어 출범을 앞두고 수익성 회복을 확인시켜 7월 이후 반등 국면을 뒷받침했어요.",
  "https://news.mtn.co.kr/article/2026110916422268897", "머니투데이방송")
# ---- 현대무벡스(319400)
N("319400", "2025-12-22", "+", "cat", "로보틱스 추가 수주 기대에 +20% 사상 최고가",
  "한국콜마 등 AGV 100여 대 수주와 평택 대형 제조공장 AI 피킹로봇 공급에 이어, 같은 고객사 다른 사업장 추가 수주와 500억~700억원 규모 유럽 프로젝트 입찰이 막바지라는 전망이 나오면서 12월 22일 주가가 장중 20.07% 오른 1만6330원으로 사상 최고가를 썼어요. 부국증권은 로보틱스 사업부 수주 확대로 내년 실적이 크게 개선될 것으로 봤어요. 물류자동화 회사가 로봇주로 재평가받은 것이 대세 상승 국면의 핵심이었어요.",
  "https://view.asiae.co.kr/article/2025122210071473324", "아시아경제")
N("319400", "2026-06-08", "-", "cat", "현대엘리베이터, 무벡스 900만주(3335억) 처분 결정",
  "최대주주 현대엘리베이터가 현대무벡스 주식 900만주를 6월 2일 종가 3만7050원 기준 약 3335억원에 7월 6일~8월 4일 시간외 거래로 처분한다고 밝혔어요. 지분율은 48.9%에서 40.79%로 낮아져요. 주가가 지난해 말 1만원대에서 5월 4만원을 넘자 모회사가 차익 실현에 나선 것으로, 대규모 물량 출회 부담이 5월 고점 이후 하락 국면을 키운 요인이었어요.",
  "https://ceoscoredaily.com/page/view/2026060810150228606", "CEO스코어데일리")
