N("161000", "2025-04-25", "+", "cat", "나트륨이온 배터리 테마 부각, 장중 상한가 1만360원",
  "CATL의 2세대 나트륨이온 배터리 공개와 러시아 ESS 계획 소식으로 나트륨 배터리가 주목받자 음극재용 하드카본을 개발 중인 애경케미칼이 4월 25일 오전 28.36% 오른 1만230원에 거래됐고 장중 상한가 1만360원을 찍었어요. 애경케미칼은 2012년 하드카본을 출시했고 방전 용량을 높인 신제품 상용화를 추진 중이에요. 실적보다 2차전지 신소재 테마가 2025년 3월 저점 이후 반등의 첫 촉매였어요.",
  "https://view.asiae.co.kr/article/2025042510123101560", "아시아경제")
N("161000", "2026-03-30", "+", "cat", "휴머노이드용 탄소섬유 경량 소재 상용화에 상한가 1만4820원",
  "애경케미칼은 3월 30일 개장 직후 가격제한폭까지 올라 30.00% 상승한 1만4820원을 기록했고 거래대금은 1751억원을 넘었어요. 휴머노이드 로봇·모빌리티용 탄소섬유 SMC와 초고속 경화 탄소섬유 프리프레그 상용화 소식이 촉매였고, 회사는 국내외 고객사 기술 문의와 납품 의뢰가 크게 늘었다고 밝혔어요. 구체적인 계약 내용은 공개되지 않았어요. 로봇 소재 테마가 2026년 4월 상승 국면 고점 직전의 마지막 급등을 이끌었어요.",
  "https://www.wikitree.co.kr/articles/1128664", "위키트리")
