N("093370", "2026-06-18", "-", "val", "연초 대비 +136%·PER 93배, 고점서 밸류에이션 부담 부각",
  "후성 주가는 연초부터 6월 17일까지 136.29% 올라 2022년 이후 최고가 수준에 이르렀고 장중 고점 기준 상승률은 218%였어요. 삼성증권은 WF6 수급 불안, 중동 전쟁·중국 수출 제한에 따른 불산 가격 상승, 약 2000톤 LiPF6 설비 풀가동을 근거로 들었지만 2026년 예상 실적 기준 PER이 93배(한텍 지분가치 반영 시 83배)에 달해 추가 상승은 실적 개선 속도에 달렸다고 봤어요. 투자의견은 제시하지 않았어요. 투자경고 지정과 높은 밸류에이션이 6~7월 -55% 급락 국면의 출발점이었어요.",
  "https://www.fnnews.com/news/202606180716328127", "파이낸셜뉴스")

