N("065350", "2024-02-21", "+", "cat", "PCPOSOS 초전도체 APS 발표 기대에 상한가, 연초 대비 +257%",
  "신성델타테크가 2월 21일 29.95% 오른 14만8,400원으로 상한가를 기록했어요. 1월 2일 시가 4만1,550원 대비 약 257% 오른 수준이에요. 퀀텀에너지연구소 연구진이 3월 4일 미국물리학회(APS)에서 초전도체라고 주장하는 PCPOSOS 결과를 발표한다는 소식에 초전도체 테마가 되살아났는데, 회사와의 연결고리는 퀀텀에너지연구소 초기 투자사 엘앤에스벤처캐피탈 지분 정도였어요. 2022년 말부터 이어진 +1477% 테마 급등 국면의 정점이었어요.",
  "https://www.sidae.com/article/2024022016524465412", "시대일보")
N("065350", "2024-12-23", "+", "cat", "퀀텀에너지연구소 협업 공지 후 10월부터 +105%",
  "신성델타테크는 10월 2일 홈페이지에 퀀텀에너지연구소와 초전도체 신사업을 협력 중이라며 '좋은 일이 있을 것'이라는 공지를 올렸어요. 이후 주가가 5만원대에서 10만3,000원대로 105% 넘게 올라 코스닥 시총 순위가 31위에서 10위로 뛰었어요. 퀀텀에너지연구소가 세운 에이에스씨랩에 1,500만원(지분 15%)을 투자하고 관련 인력도 채용했어요. 8월에 초전도체와 관계없다고 부인했다가 협업을 밝힌 것이 2024년 10~12월 +159% 재급등의 출발점이었어요.",
  "https://www.ajunews.com/view/20241223112516934", "아주경제")
