N("078600", "2024-06-11", "+", "cat", "실리콘 음극재 적용 차종 2종→9종, 장중 +20%",
  "대주전자재료가 실리콘 음극재 적용 차종이 2종에서 9종으로 늘었다고 밝히자 주가가 오전 20.23% 오른 14만8,000원, 장중 15만2,600원까지 올라 VI가 발동됐어요. 실리콘 음극재 수요가 지난해 1만t에서 내년 3.9만t으로 늘 것이라는 전망과 테슬라 신형 2170 배터리 적용 기대도 거론됐지만 고객 확정은 아니었어요. 2019년부터 이어진 +893% 상승 국면의 고점을 만든 사건이에요.",
  "https://news.mtn.co.kr/news-detail/2024061110120685093", "머니투데이방송")
# ---- 이랜텍(054210)
N("054210", "2026-03-25", "+", "news", "SK증권 목표가 1.3만→1.8만, 배터리팩 신사업 리레이팅",
  "SK증권은 이랜텍 목표주가를 1만3,000원에서 1만8,000원으로 올리고 올해 매출 9,041억원, 영업이익 546억원을 추정하며 PER 7배로 저평가라고 봤어요. LG에너지솔루션향 중대형 배터리팩 매출이 386억원에서 1,227억원으로, 체리자동차향 46시리즈 배터리팩이 첫해 300억원대로 늘고 유럽향 LFP ESS BMS 매출도 생긴다는 전망이에요. 2024년을 실적 저점으로 반등한 흐름이 2025년 1월~2026년 4월 +170% 상승 국면을 뒷받침했어요.",
  "https://core.asiae.co.kr/article/2026032507544507166", "아시아경제")
# ---- 에코프로(086520) 추가2
N("086520", "2025-10-17", "+", "news", "ESS·전기차 판매 사상 최대 기대에 하루 +27%",
  "에코프로가 10월 17일 27.04% 오른 7만3,300원에 마감했고 에코프로비엠(+12.59%), 삼성SDI(+8.26%)도 함께 올랐어요. 테슬라·플루언스 주가 상승에 따른 ESS 기대, 9월 세계 전기차 판매 210만대(+26%) 사상 최대, LG에너지솔루션 3분기 영업이익 6,013억원이 투자심리를 살렸어요. 증권가는 순환매 성격이 강하고 NCM 양극재의 ESS 직접 수혜가 낮다며 주의를 당부했지만, 2025년 5월 이후 +332% 상승 국면을 가속한 날이에요.",
  "https://www.mt.co.kr/article/2025101716205256107", "머니투데이")
# ---- 디에이테크놀로지(196490)
N("196490", "2026-04-09", "-", "cat", "2년 연속 감사의견 미달로 상장폐지 대상 11개사 포함",
  "디에이테크놀로지는 코스닥 상장사 중 2년 연속 감사의견 미달로 상장폐지 대상에 오른 11개사에 포함됐어요. 2년 연속인 경우 올해 중 기업심사위원회 심의를 거쳐 상폐가 결정되는 구조예요. 주가가 사실상 -100%까지 떨어진 하락 국면의 종착점이 감사의견 미달에 따른 상장폐지 절차였어요.",
  "https://news.bizwatch.co.kr/article/market/2026/04/09/0018", "비즈니스워치")
# ---- 엘앤에프(066970) 추가
N("066970", "2026-03-25", "+", "cat", "삼성SDI 1.6조 LFP 양극재 계약에 이틀 +11.5%·+16.2%",
  "엘앤에프가 삼성SDI와 1조6,067억원 규모 ESS용 LFP 양극재 공급 계약(2026년 3월~2029년 12월, 2032년까지 자동 연장)을 맺자 주가가 24일 11.51%, 25일 16.24% 올라 14만5,300원에 마감했어요. 1분기 영업이익 컨센서스는 428억원이었지만 KB증권은 883억원을 제시하는 등 추정치 대부분이 이를 웃돌았고, 리튬 가격이 작년 말보다 23.9% 올라 재고평가손실 환입도 기대됐어요. 테슬라 유럽 판매가 12개월 만에 성장으로 돌아선 것도 힘을 보태, 상승 국면 막바지를 가속한 핵심 촉매예요.",
  "https://www.hankyung.com/article/2026032552606", "한국경제")
