N("312610", "2026-10-30", "-", "cat", "시가총액 미달로 상장폐지 결정, 정리매매 중 거래정지",
  "에이에프더블류는 시가총액 미달로 상장폐지가 결정된 코스닥 8개사 중 하나로, 정리매매가 진행되던 중 거래가 정지됐어요. 법원이 일부 기업의 상폐 효력정지 가처분을 인용하면서 거래소가 후속 절차를 유예했지만, 거래정지는 그대로 유지됐어요. 2023년 4월 이후 -99% 하락 국면이 상장폐지 절차로 이어진 결말이에요.",
  "https://dealsite.co.kr/articles/171538", "딜사이트")
N("247540", "2026-08-09", "-", "earn", "2분기 영업이익 180억, 전년 대비 -63%",
  "에코프로비엠의 2026년 2분기 매출은 5,767억원으로 전년보다 26% 줄었고, 영업이익은 180억원으로 63.2% 급감했어요. 북미 전기차 수요 정체와 유럽 완성차의 차종 전환에 따른 출하 지연이 원인이었고, 전동공구·e바이크용 판매(전분기 대비 +28%)와 헝가리 공장 덕분에 흑자만 겨우 지켰어요. 1월 고점 이후 하락 국면에서 실적 부진이 숫자로 확인된 분기예요.",
  "https://dealsite.co.kr/articles/166811", "딜사이트")
