N("278280", "2025-08-25", "+", "news", "리서치알음 'LiFSI 성장' 리포트, 2025년 영업이익 155억 흑자전환 전망",
  "리서치알음은 천보의 2025년 매출을 1,665억원(+14.9%), 영업이익을 155억원으로 흑자 전환할 것으로 내다봤어요. 세계 최초로 LiFSI를 상용화한 기술력과, 탄산리튬 기반 공정을 적용한 새만금 전용 공장이 제조원가를 30% 넘게 낮출 수 있다는 점을 근거로 들었어요. 2025년 3월 저점 이후 +122% 반등 국면에서 흑자 전환과 LiFSI 성장 기대를 뒷받침한 분석이에요.",
  "https://view.asiae.co.kr/article/2025082507590246997", "아시아경제")
N("278280", "2026-01-02", "-", "earn", "키움 '4분기 영업이익 9억, 컨센서스 15억 하회' 전망·1분기 적자전환 예상",
  "키움증권은 천보의 4분기 매출을 334억원, 영업이익을 9억원(-63%)으로 추정해 컨센서스(매출 374억원, 영업이익 15억원)를 밑돌 것으로 봤고, 2026년 1분기는 새만금 공장 초기 가동비 부담으로 적자 전환을 예상했어요. 목표가는 4.5만원에서 5.2만원으로 올렸지만 의견은 '시장수익률'을 유지하며, 오버행과 실적 회복 지연을 들어 추세 반등은 이르다고 판단했어요. 2025년 10월 고점 이후 하락 국면에서 실적 기대를 낮춘 근거예요.",
  "https://www.ajunews.com/view/20260102083841299", "아주경제")
