  "하나기술의 2026년 상반기 매출은 136억원으로 전년 동기 316억원보다 57% 줄었고, 영업손실은 100억원으로 전년의 두 배를 넘었어요. 수주잔고는 인도 고객사 약 3,190억원을 포함해 4,825억원까지 늘었지만, 인도향 납품은 하반기에야 시작될 예정이라 매출 공백이 이어졌어요. 2025년 11월 고점 이후 -67% 하락 국면에서 수주가 실적으로 이어지지 못한 점을 보여준 실적이에요.",
